(function () {
  'use strict';

  // Приложение работает и в корне домена, и в подпапке reverse proxy
  // (например https://bimmax.pro/planfakt/). Базовый адрес берётся из адреса
  // самой страницы: маршруты хранятся в hash, поэтому путь всегда указывает
  // на каталог приложения. Все запросы к API строятся от этой базы —
  // абсолютный «/api/...» в подпапке уходил бы мимо приложения.
  const APP_BASE = (() => {
    const path = String(location.pathname || '/');
    return path.endsWith('/') ? path : path.replace(/[^/]*$/, '');
  })();
  const apiPath = (route) => APP_BASE + String(route || '').replace(/^\/+/, '');

  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
  const esc = (value) => String(value ?? '').replace(/[&<>'"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[c]));
  const fmt = (value, digits = 0) => new Intl.NumberFormat('ru-RU', { maximumFractionDigits: digits }).format(Number(value || 0));
  const formatDate = (date, options = { day: 'numeric', month: 'long', year: 'numeric' }) => new Intl.DateTimeFormat('ru-RU', options).format(new Date(`${date}T12:00:00`));
  const today = new Date().toISOString().slice(0, 10);
  const roleNames = { admin: 'Администратор', manager: 'Руководитель', responsible: 'Ответственный' };
  const actionNames = { 'schedule.upload': 'Загружен график', 'schedule.replace': 'Заменён график', 'report.submit': 'Отправлен отчёт', 'milestone.create': 'Создана веха', 'project.create': 'Создан объект', 'project.update': 'Изменён объект', 'organization.create': 'Создан подрядчик', 'organization.update': 'Изменён подрядчик', 'user.create': 'Создан пользователь', 'user.update': 'Изменён пользователь', 'user.telegram_link': 'Привязан Telegram ID', 'auth.login': 'Вход в систему' };
  const defaultImportMapping = { sheet: 'СМГ', dataStartRow: 3, hierarchyColumns: ['C', 'D', 'E'], columns: { number: 'A', code: 'B', name: 'F', organization: 'G', unit: 'I', total: 'J', priorActual: 'K', remaining: 'L', monthlyPlan: 'M', rowType: 'N', firstDay: 'O' }, planRowValue: 'План', factRowOffset: 1 };
  let scheduleMappingSaveTimer = null;

  const icons = {
    home: '⌂', dashboard: '◫', planfact: '▥', contractors: '◇', reports: '▤', resources: '♙', photos: '▧', milestones: '⚑', schedules: '⇧', archive: '□',
    projects: '⬡', users: '♤', organizations: '◈', dictionaries: '≡', settings: '⚙', audit: '↻', profile: '♧', report: '＋', history: '◷', export: '⇩', administration: '⚙', analysis: '◫'
  };

  const navByRole = {
    responsible: [
      ['Основное', [['home', 'Главная'], ['report', 'Отчёт за сегодня'], ['history', 'История отчётов'], ['profile', 'Профиль']]]
    ],
    manager: [
      ['Аналитика', [['dashboard', 'Дашборд'], ['planfact', 'План / Факт'], ['contractors', 'Подрядчики']]],
      ['Контроль', [['reports', 'Отчёты'], ['resources', 'Люди и техника'], ['photos', 'Фотографии'], ['milestones', 'Вехи']]],
      ['Данные', [['schedules', 'Графики'], ['archive', 'Архив']]]
    ],
    admin: [
      ['Данные', [['planfact', 'План / Факт'], ['schedules', 'Загрузить таблицу'], ['export', 'Выгрузить План / Факт'], ['analysis', 'Анализ']]],
      ['Система', [['administration', 'Администрирование']]]
    ]
  };

  const state = {
    user: null, projects: [], organizations: [], dictionaries: {}, projectId: localStorage.getItem('pf_project') || '', route: '', role: '', authMode: 'checking', telegramInitData: '', pendingTelegramId: '', projectChoices: [],
    works: [], reports: [], analytics: null, filters: { period: '7days', endDate: '', organizationId: 'all', workId: 'all', delays: false, sort: 'lag' }, adminTab: 'projects', adminSnapshot: null,
    draft: { step: 0, facts: [], workers: [], equipment: [], photos: [], noFacts: false, noWork: false }, uploadHierarchy: ['C', 'D', 'E']
  };

  async function api(url, options = {}) {
    const response = await fetch(apiPath(url), { credentials: 'same-origin', headers: { 'Content-Type': 'application/json', ...(options.headers || {}) }, ...options });
    let data = null;
    try { data = await response.json(); } catch { data = {}; }
    if (response.status === 401 && !url.includes('/auth/')) showLogin();
    if (!response.ok) { const error = new Error(data.error || 'Не удалось выполнить запрос'); Object.assign(error, { status: response.status, code: data.code, data }); throw error; }
    return data;
  }

  function initials(name) {
    return String(name || '').split(/\s+/).slice(0, 2).map(x => x[0]).join('').toUpperCase();
  }

  function toast(message, type = '') {
    const el = $('#toast');
    el.textContent = message; el.className = `toast show ${type}`;
    clearTimeout(toast.timer); toast.timer = setTimeout(() => el.className = 'toast', 3200);
  }

  function loading() {
    $('#content').innerHTML = `<div class="page-head"><div><div class="skeleton" style="width:90px"></div><div class="skeleton" style="width:250px;height:28px;margin-top:10px"></div></div></div><div class="kpi-grid">${'<div class="card kpi"><div class="skeleton"></div><div class="skeleton" style="height:32px;margin-top:20px"></div></div>'.repeat(4)}</div>`;
  }

  function showAuthCheck(error = '') {
    state.user = null;
    state.authMode = 'checking';
    $('#login-screen').classList.remove('hidden');
    $('#app').classList.add('hidden');
    $('#auth-form').classList.add('hidden');
    $('#project-choice').classList.add('hidden');
    $('#auth-check').classList.remove('hidden');
    $('#auth-check-spinner').classList.toggle('hidden', Boolean(error));
    $('#auth-check-title').textContent = error ? 'Не удалось проверить Telegram ID' : 'Проверяем Telegram ID';
    $('#auth-check-text').textContent = error || 'Ищем привязанный аккаунт…';
    $('#auth-retry').classList.toggle('hidden', !error);
  }

  function showLogin(mode = 'web', telegramId = '') {
    state.user = null;
    state.authMode = mode === 'telegram' ? 'telegram-link' : 'web';
    $('#login-screen').classList.remove('hidden');
    $('#auth-check').classList.add('hidden');
    $('#project-choice').classList.add('hidden');
    $('#auth-form').classList.remove('hidden');
    const telegram = mode === 'telegram';
    if (telegramId) state.pendingTelegramId = telegramId;
    $('#telegram-link-note').classList.toggle('hidden', !telegram);
    $('#telegram-link-confirm-wrap').classList.toggle('hidden', !telegram);
    $('#telegram-link-confirm').required = telegram;
    $('#telegram-link-confirm').checked = false;
    $('#telegram-link-id').textContent = state.pendingTelegramId || '';
    $('#login-title').textContent = telegram ? 'Привязка аккаунта' : 'План / Факт';
    $('#login-subtitle').textContent = telegram ? 'Подтвердите учётную запись логином и паролем' : 'Введите логин и пароль для входа в блок';
    $('#login-submit-text').textContent = telegram ? 'Войти и привязать Telegram' : 'Войти';
    $('#login-error').textContent = '';
    $('#login').focus();
  }

  function projectLandingRoute(role) {
    if (role === 'responsible') return 'home';
    if (role === 'manager' || role === 'admin') return 'planfact';
    return 'profile';
  }

  function showProjectChoice(data) {
    state.user = data.user;
    state.projectId = '';
    state.authMode = 'telegram-project';
    state.projectChoices = data.projectChoices || [];
    $('#login-screen').classList.remove('hidden');
    $('#app').classList.add('hidden');
    $('#auth-check').classList.add('hidden');
    $('#auth-form').classList.add('hidden');
    $('#project-choice').classList.remove('hidden');
    $('#project-choice-error').textContent = '';
    $('#project-choice-list').innerHTML = state.projectChoices.map(project => {
      const customer = project.customerOrganization?.fullName || project.customerOrganization?.portalName || 'Организация-заказчик';
      return `<button class="project-choice" type="button" data-auth-project="${esc(project.id)}"><span class="project-choice__icon">⌂</span><span class="project-choice__copy"><b>${esc(project.name)}</b><small>${esc(customer)} · ${project.contractors?.length || 0} подрядчиков</small></span><span class="project-choice__role">${esc(roleNames[project.role] || project.role)}</span></button>`;
    }).join('');
  }

  async function selectTelegramProject(projectId) {
    const error = $('#project-choice-error');
    error.textContent = '';
    const buttons = $$('.project-choice');
    buttons.forEach(button => { button.disabled = true; });
    try {
      const data = await api('/api/auth/telegram/select-project', { method: 'POST', body: JSON.stringify({ initData: state.telegramInitData, projectId }) });
      await boot(data, { telegramLaunch: true });
    } catch (requestError) {
      error.textContent = requestError.message;
      buttons.forEach(button => { button.disabled = false; });
    }
  }

  async function boot(data, options = {}) {
    if (options.telegramLaunch && data.requiresProjectSelection) return showProjectChoice(data);
    state.user = data.user;
    state.authMode = 'authenticated';
    const full = data.projects ? data : await api('/api/bootstrap');
    state.projects = full.projects; state.organizations = full.organizations; state.dictionaries = full.dictionaries;
    if (data.projectId && state.projects.some(p => p.id === data.projectId)) state.projectId = data.projectId;
    else if (!state.projects.some(p => p.id === state.projectId)) state.projectId = state.projects[0]?.id || '';
    setContext();
    $('#login-screen').classList.add('hidden'); $('#app').classList.remove('hidden');
    renderChrome();
    const defaultRoute = data.startRoute || projectLandingRoute(state.role);
    const requestedRoute = options.telegramLaunch ? defaultRoute : (location.hash.slice(1) || defaultRoute);
    navigate(requestedRoute);
  }

  function setContext() {
    const a = state.user.assignments.find(x => x.projectId === state.projectId);
    state.role = a?.role || '';
    localStorage.setItem('pf_project', state.projectId);
  }

  function renderChrome() {
    const project = state.projects.find(p => p.id === state.projectId);
    $('#project-name').textContent = project?.shortName || 'Выберите объект';
    $('#user-name').textContent = state.user.name;
    $('#user-role').textContent = roleNames[state.role] || state.role;
    $('#user-avatar').textContent = initials(state.user.name);
    const groups = navByRole[state.role] || [];
    $('#main-nav').innerHTML = groups.map(([title, items]) => `<div class="nav-group">${esc(title)}</div>${items.map(([key, label]) => `<button class="nav-item ${key === state.route ? 'active' : ''}" data-route="${key}"><span class="nav-icon">${icons[key]}</span><span>${esc(label)}</span>${key === 'planfact' && state.role !== 'responsible' ? '<span class="nav-badge">3</span>' : ''}</button>`).join('')}`).join('');
    const flat = groups.flatMap(g => g[1]);
    const preferred = state.role === 'responsible' ? ['home', 'report', 'history', 'profile'] : state.role === 'admin' ? ['planfact', 'schedules', 'export', 'administration'] : ['planfact', 'dashboard', 'reports', 'schedules'];
    $('#mobile-nav').innerHTML = preferred.filter(key => flat.some(x => x[0] === key)).map(key => { const item = flat.find(x => x[0] === key); return `<button data-route="${key}" class="${key === state.route ? 'active' : ''}"><span>${icons[key]}</span>${esc(item[1])}</button>`; }).join('');
  }

  async function navigate(route) {
    const allowed = (navByRole[state.role] || []).flatMap(g => g[1]).map(x => x[0]);
    const hiddenAllowed = state.role !== 'responsible' ? ['report'] : [];
    if (!allowed.includes(route) && !hiddenAllowed.includes(route)) route = projectLandingRoute(state.role);
    state.route = route; location.hash = route; renderChrome(); closePopovers(); loading();
    try {
      const handlers = { home: renderHome, dashboard: renderDashboard, planfact: renderPlanFact, contractors: renderContractors, report: renderReport, history: renderReports, reports: renderReports, resources: renderResources, photos: renderPhotos, milestones: renderMilestones, schedules: renderSchedules, export: renderExport, analysis: renderAnalysis, administration: renderAdministration, archive: renderArchive, projects: renderProjects, users: renderUsers, organizations: renderOrganizations, dictionaries: renderDictionaries, audit: renderAudit, settings: renderSettings, profile: renderProfile };
      await (handlers[route] || renderHome)();
      $('#content').focus({ preventScroll: true });
    } catch (error) { $('#content').innerHTML = errorState(error.message); }
  }

  function closePopovers() {
    $('#overlay').classList.add('hidden'); $('#project-popover').classList.add('hidden'); $('#user-popover').classList.add('hidden'); $('.sidebar').classList.remove('open');
  }

  function errorState(message) {
    return `<div class="card empty"><div><div class="empty-icon">!</div><h3>Не удалось загрузить данные</h3><p>${esc(message)}</p><button class="button button--secondary" data-action="retry">Повторить</button></div></div>`;
  }

  function pageHead(title, subtitle, actions = '') {
    return `<div class="page-head"><div><p class="eyebrow">${state.projects.find(p => p.id === state.projectId)?.shortName || ''}</p><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${actions ? `<div class="page-actions">${actions}</div>` : ''}</div>`;
  }

  async function loadCore() {
    const [works, reports] = await Promise.all([api(`/api/works?projectId=${state.projectId}`), api(`/api/reports?projectId=${state.projectId}`)]);
    state.works = works.works; state.reports = reports.reports;
  }

  function org(id) { return state.organizations.find(o => o.id === id); }

  function projectToday() {
    const timezone = state.projects.find(project => project.id === state.projectId)?.timezone || 'Europe/Moscow';
    try {
      const parts = new Intl.DateTimeFormat('en-CA', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date());
      const values = Object.fromEntries(parts.map(part => [part.type, part.value]));
      return `${values.year}-${values.month}-${values.day}`;
    } catch { return today; }
  }

  async function renderHome() {
    await loadCore();
    const mineToday = state.reports.find(r => r.reportDate === today);
    const assignedOrgIds = state.user.assignments.find(a => a.projectId === state.projectId)?.organizationIds || [];
    const assignedOrg = org(assignedOrgIds[0]);
    const recent = state.reports.slice(0, 4);
    $('#content').innerHTML = `${pageHead(`Здравствуйте, ${esc(state.user.name.split(' ')[0])}`, 'Сегодняшний отчёт займёт несколько минут')}
      <div class="today-banner"><div class="date-box">${new Date().getDate()}</div><div><h2>${formatDate(today, { weekday:'long', day:'numeric', month:'long' })}</h2><p>${esc(assignedOrg?.shortName || 'Организация не назначена')} · ${state.works.length} доступных работ</p></div><span class="report-status">${mineToday ? `Отправлен в ${new Date(mineToday.sentAt).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}` : 'Отчёт не отправлен'}</span></div>
      <div class="list-grid">
        <article class="card mini-card"><div class="mini-card-head"><div><h3>Выполненные работы</h3><p>Доступны по вашей организации</p></div><span class="kpi-icon">▥</span></div><div class="mini-stat"><strong>${state.works.length}</strong><span>позиций</span></div></article>
        <article class="card mini-card"><div class="mini-card-head"><div><h3>Последний отчёт</h3><p>${recent[0] ? formatDate(recent[0].reportDate) : 'Нет данных'}</p></div><span class="kpi-icon">✓</span></div><div class="mini-stat"><strong>${recent[0]?.facts.length || 0}</strong><span>работ указано</span></div></article>
        <article class="card mini-card"><div class="mini-card-head"><div><h3>Доступный остаток</h3><p>По всем вашим работам</p></div><span class="kpi-icon">◴</span></div><div class="mini-stat"><strong>${fmt(state.works.reduce((s,w)=>s+w.remaining,0),1)}</strong><span>единиц</span></div></article>
      </div>
      <div class="card card-pad" style="margin-top:14px;display:flex;align-items:center;gap:18px;flex-wrap:wrap"><div style="flex:1;min-width:220px"><h2 style="margin:0 0 6px;font-size:17px">${mineToday ? 'Отчёт за сегодня уже отправлен' : 'Готовы заполнить отчёт?'}</h2><p class="muted" style="margin:0;font-size:11px">Добавьте работы, людей, технику и фотографии с площадки.</p></div><button class="button button--primary" data-route="report">${mineToday ? 'Добавить ещё отчёт' : 'Начать отчёт'} →</button></div>
      ${recent.length ? `<div class="card" style="margin-top:14px"><div class="card-head"><div><h3>Последние отчёты</h3><p>Ваша история отправок</p></div><button class="button button--secondary button--small" data-route="history">Все отчёты</button></div>${reportsTable(recent, true)}</div>` : ''}`;
  }

  async function getAnalytics() {
    const f = state.filters;
    if (!f.endDate) f.endDate = projectToday();
    const params = new URLSearchParams({ projectId: state.projectId, period: f.period, organizationId: f.organizationId, workId: f.workId, end: f.endDate });
    state.analytics = await api(`/api/analytics?${params}`);
    return state.analytics;
  }

  function filterBar() {
    const availableWorks = state.works.filter(work => state.filters.organizationId === 'all' || work.organizationId === state.filters.organizationId);
    return `<div class="card filter-bar"><div class="segmented">${[['today','Сегодня'],['3days','3 дня'],['7days','7 дней'],['month','Месяц']].map(([k,l])=>`<button data-period="${k}" class="${state.filters.period===k?'active':''}">${l}</button>`).join('')}</div>
      <label class="compact-field">Дата среза<input class="filter-date" id="end-date-filter" type="date" value="${esc(state.filters.endDate || projectToday())}" max="9999-12-31"></label>
      <select class="filter-select" id="org-filter" aria-label="Подрядчик"><option value="all">Все подрядчики</option>${state.organizations.filter(o=>o.projectIds.includes(state.projectId)).map(o=>`<option value="${o.id}" ${state.filters.organizationId===o.id?'selected':''}>${esc(o.shortName)}</option>`).join('')}</select>
      <select class="filter-select" id="work-filter" aria-label="Работа"><option value="all">Все работы</option>${availableWorks.map(w=>`<option value="${w.id}" ${state.filters.workId===w.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select>
      <div class="filter-spacer"></div><label class="check-control"><input id="delays-filter" type="checkbox" ${state.filters.delays?'checked':''}> Только отставания</label></div>`;
  }

  function chartSvg(days) {
    if (!days.length) return '';
    const w=720,h=210,p=28,max=Math.max(1,...days.flatMap(d=>[d.plan,d.actual]));
    const point=(d,i,key)=>`${p+i*((w-p*2)/Math.max(1,days.length-1))},${h-p-(d[key]/max)*(h-p*2)}`;
    const grid=[0,.25,.5,.75,1].map(n=>`<line x1="${p}" y1="${h-p-n*(h-p*2)}" x2="${w-p}" y2="${h-p-n*(h-p*2)}" stroke="#e7ebf1"/><text x="0" y="${h-p-n*(h-p*2)+3}" fill="#8b96a6" font-size="9">${fmt(max*n)}</text>`).join('');
    const labels=days.map((d,i)=> i%Math.ceil(days.length/7)===0||i===days.length-1?`<text x="${p+i*((w-p*2)/Math.max(1,days.length-1))}" y="205" text-anchor="middle" fill="#8b96a6" font-size="9">${d.date.slice(8)}</text>`:'').join('');
    return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${grid}<polyline points="${days.map((d,i)=>point(d,i,'plan')).join(' ')}" fill="none" stroke="#246bfe" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${days.map((d,i)=>point(d,i,'actual')).join(' ')}" fill="none" stroke="#13a66a" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${days.map((d,i)=>`<circle cx="${point(d,i,'actual').split(',')[0]}" cy="${point(d,i,'actual').split(',')[1]}" r="3" fill="#fff" stroke="#13a66a" stroke-width="2"/>`).join('')}${labels}</svg>`;
  }

  async function renderDashboard() {
    await loadCore(); const a = await getAnalytics();
    const completion = a.totals.cumulativePlan ? Math.round(a.totals.cumulativeActual/a.totals.cumulativePlan*100) : 0;
    const delayed = a.rows.filter(r=>r.deviation<0).sort((x,y)=>x.deviation-y.deviation);
    const reportsToday = state.reports.filter(r=>r.reportDate===today).length;
    const totalOrgs = state.organizations.filter(o=>o.projectIds.includes(state.projectId)).length;
    $('#content').innerHTML = `${pageHead('Дашборд','Оперативная картина выполнения производственного графика',`<button class="button button--secondary" data-action="export-page">⇩ Экспорт</button><button class="button button--primary" data-route="reports">Открыть отчёты</button>`)}${filterBar()}
      <div class="kpi-grid">
        ${kpi('План за период',fmt(a.totals.plan,1),'единиц объёма','▥')}${kpi('Факт за период',fmt(a.totals.actual,1),`${a.totals.actual-a.totals.plan>=0?'+':''}${fmt(a.totals.actual-a.totals.plan,1)} к плану`,'✓',a.totals.actual>=a.totals.plan?'positive':'negative')}${kpi('Выполнение',`${completion}%`,'накопительным итогом','◴',completion>=100?'positive':'')}${kpi('Отчёты сегодня',`${reportsToday} / ${totalOrgs}`,reportsToday>=totalOrgs?'все подрядчики отчитались':'ожидаются отчёты','▤',reportsToday>=totalOrgs?'positive':'negative')}
      </div>
      <div class="dashboard-grid">
        <section class="card chart-card"><div class="card-head"><div><h3>Динамика выполнения</h3><p>${formatDate(a.from)} — ${formatDate(a.to)}</p></div><div class="chart-legend"><span>План</span><span>Факт</span></div></div><div class="chart-wrap">${chartSvg(a.days)}</div></section>
        <section class="card"><div class="card-head"><div><h3>Статус работ</h3><p>Накопительный итог</p></div></div><div class="donut-wrap"><div class="donut" style="--percent:${Math.min(100,completion)}%"><span><strong>${completion}%</strong><small>выполнено</small></span></div><div class="donut-notes"><div><span>В графике</span><b>${a.rows.filter(r=>r.deviation>=0).length}</b></div><div><span>С отставанием</span><b>${delayed.length}</b></div><div><span>Всего работ</span><b>${a.rows.length}</b></div></div></div></section>
      </div>
      <section class="card"><div class="card-head"><div><h3>Работы с наибольшим отставанием</h3><p>Требуют внимания руководителя</p></div><button class="button button--secondary button--small" data-route="planfact">Смотреть все</button></div>${workTable(delayed.slice(0,5))}</section>`;
  }

  function kpi(label,value,subtitle,icon,tone='') { return `<article class="card kpi"><div class="kpi-top"><span>${esc(label)}</span><span class="kpi-icon">${icon}</span></div><strong>${value}</strong><small class="${tone}">${esc(subtitle)}</small></article>`; }

  function rowStatus(row) {
    if (row.status === 'lag') return { tone: 'lag', label: 'Отставание' };
    if (row.status === 'ahead') return { tone: 'ok', label: 'Опережение' };
    if (row.status === 'not_planned') return { tone: 'neutral', label: 'Нет плана' };
    return { tone: 'ok', label: 'В графике' };
  }

  function workTable(rows, detailed = false, emptyTitle = 'Отставаний нет', emptyText = 'Все выбранные работы идут по графику.') {
    if (!rows.length) return `<div class="empty"><div><div class="empty-icon">✓</div><h3>${esc(emptyTitle)}</h3><p>${esc(emptyText)}</p></div></div>`;
    const headings = detailed ? '<th class="num">План периода</th><th class="num">Факт периода</th><th class="num">Δ периода</th><th class="num">План накоп.</th><th class="num">Факт накоп.</th><th class="num">Δ накоп.</th>' : '<th class="num">План</th><th class="num">Факт</th><th class="num">Отклонение</th>';
    return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Работа</th><th>Подрядчик</th>${headings}<th>Выполнение</th><th>Статус</th></tr></thead><tbody>${rows.map(r=>{const pct=r.completionPercent;const status=rowStatus(r);const values=detailed?`<td class="num">${fmt(r.plan,1)}</td><td class="num"><b>${fmt(r.actual,1)}</b></td><td class="num ${r.periodDeviation<0?'delta-negative':r.periodDeviation>0?'delta-positive':''}">${r.periodDeviation>0?'+':''}${fmt(r.periodDeviation,1)}</td><td class="num">${fmt(r.cumulativePlan,1)}</td><td class="num"><b>${fmt(r.cumulativeActual,1)}</b></td><td class="num ${r.deviation<0?'delta-negative':r.deviation>0?'delta-positive':''}">${r.deviation>0?'+':''}${fmt(r.deviation,1)}</td>`:`<td class="num">${fmt(r.cumulativePlan,1)}</td><td class="num"><b>${fmt(r.cumulativeActual,1)}</b></td><td class="num ${r.deviation<0?'delta-negative':r.deviation>0?'delta-positive':''}">${r.deviation>0?'+':''}${fmt(r.deviation,1)}</td>`;return `<tr><td><div class="work-name"><b>${esc(r.name)}</b><small>${esc(r.code)} · ${esc(r.unit)}</small></div></td><td><span class="org-pill">${esc(r.organization?.shortName||'—')}</span></td>${values}<td>${pct===null?'<small class="muted">—</small>':`<div class="progress"><i style="width:${Math.min(100,Math.max(0,pct))}%"></i></div><small>${fmt(pct,1)}%</small>`}</td><td><span class="status-pill ${status.tone}">● ${status.label}</span></td></tr>`}).join('')}</tbody></table></div>`;
  }

  async function renderPlanFact() {
    await loadCore(); const a=await getAnalytics(); let rows=[...a.rows];
    if(state.filters.delays) rows=rows.filter(r=>r.status==='lag');
    if(state.filters.sort==='name') rows.sort((x,y)=>x.name.localeCompare(y.name,'ru'));
    else if(state.filters.sort==='completion') rows.sort((x,y)=>(x.completionPercent??Infinity)-(y.completionPercent??Infinity));
    else rows.sort((x,y)=>x.deviation-y.deviation);
    const unitSummary=a.unitTotals.map(total=>`<div class="unit-total"><b>${esc(total.unit)}</b><span>Период: <strong>${fmt(total.plan,1)}</strong> / <strong>${fmt(total.actual,1)}</strong></span><span>Накопительно: <strong>${fmt(total.cumulativePlan,1)}</strong> / <strong>${fmt(total.cumulativeActual,1)}</strong></span></div>`).join('');
    const emptyTitle=state.filters.delays?'Отставаний нет':'Работы не найдены';
    const emptyText=state.filters.delays?'По выбранным условиям все работы идут по графику.':'Измените фильтры или загрузите производственный график.';
    $('#content').innerHTML=`${pageHead('План / Факт','Плановые и фактические объёмы по работам без смешения единиц измерения',`<button class="button button--secondary" data-action="calendar">▦ Календарь</button><button class="button button--primary" data-action="new-milestone">⚑ Создать веху</button>`)}${filterBar()}
      <div class="kpi-grid">${kpi('Работ в выборке',a.summary.total,'по текущим фильтрам','▥')}${kpi('С отставанием',a.summary.lag,'по накопительному итогу','!','negative')}${kpi('В графике',a.summary.onTrack,'включая опережение','✓','positive')}${kpi('Без плана',a.summary.notPlanned,'на дату среза','—')}</div>
      ${unitSummary?`<section class="card unit-totals"><div class="unit-totals-head"><b>Итоги по единицам измерения</b><span>План / факт</span></div><div class="unit-totals-grid">${unitSummary}</div></section>`:''}
      <section class="card"><div class="card-head"><div><h3>Выполнение работ</h3><p>${formatDate(a.from)} — ${formatDate(a.to)} · ${rows.length} позиций</p></div><select id="sort-filter" class="filter-select" aria-label="Сортировка"><option value="lag" ${state.filters.sort==='lag'?'selected':''}>Сначала отставания</option><option value="completion" ${state.filters.sort==='completion'?'selected':''}>По выполнению</option><option value="name" ${state.filters.sort==='name'?'selected':''}>По названию</option></select></div>${workTable(rows,true,emptyTitle,emptyText)}</section>`;
  }

  async function renderContractors() {
    await loadCore(); const a=await getAnalytics();
    const rows=state.organizations.filter(o=>o.projectIds.includes(state.projectId)).map(o=>{const works=a.rows.filter(w=>w.organizationId===o.id);return {org:o,plan:works.reduce((s,w)=>s+w.cumulativePlan,0),actual:works.reduce((s,w)=>s+w.cumulativeActual,0),works:works.length,reports:state.reports.filter(r=>r.organizationId===o.id).length};});
    $('#content').innerHTML=`${pageHead('Подрядчики','Сводные показатели организаций на текущем объекте')}<div class="list-grid">${rows.map(r=>{const pct=r.plan?Math.round(r.actual/r.plan*100):0;return `<article class="card mini-card"><div class="mini-card-head"><div><h3>${esc(r.org.shortName)}</h3><p>${esc(r.org.fullName)}</p></div><span class="status-pill ${pct>=100?'ok':pct>=85?'wait':'lag'}">${pct}%</span></div><div class="mini-stat"><strong>${fmt(r.actual,1)}</strong><span>из ${fmt(r.plan,1)} по плану</span></div><div class="progress" style="width:100%;margin:12px 0"><i style="width:${Math.min(100,pct)}%"></i></div><p>${r.works} работ · ${r.reports} отчётов</p></article>`}).join('')}</div>`;
  }

  async function renderReport() {
    await loadCore();
    const d=state.draft,flow=reportFlow();d.step=Math.min(d.step,flow.length-1);
    $('#content').innerHTML=`${pageHead('Отчёт за сегодня',formatDate(today))}<div class="report-steps">${flow.map((item,i)=>`<button class="report-step ${i===d.step?'active':i<d.step?'done':''}" data-step="${i}"><b>${i<d.step?'✓':i+1}</b><span>${item.label}</span></button>`).join('')}</div><div class="report-layout ${state.role==='responsible'?'report-layout--wide':''}"><section class="card report-card" id="report-body">${flow[d.step].render()}</section>${state.role==='responsible'?'':reportSummary()}</div>`;
    bindReportInputs();
  }

  function reportSettings(){const assignment=state.user.assignments.find(item=>item.projectId===state.projectId),work=state.works.find(item=>item.id===state.draft.facts.find(fact=>fact.workId)?.workId),organization=org(work?.organizationId||assignment?.organizationIds?.[0]);return organization?.reportSettings||{planFact:true,workforce:false,machinery:false,photos:true};}
  function reportFlow(){const settings=reportSettings(),flow=[{label:'Работы',render:reportFacts}];if(settings.workforce)flow.push({label:'Люди',render:()=>reportRows('workers','Профессия / категория','Количество человек',state.dictionaries.professions||[])});if(settings.machinery)flow.push({label:'Механизмы',render:()=>reportRows('equipment','Наименование механизма','Количество единиц',state.dictionaries.equipment||[])});if(settings.photos!==false)flow.push({label:'Фотографии',render:reportPhotos});flow.push({label:'Проверка',render:reportReview});return flow;}

  function reportFacts() {
    if(state.role!=='responsible')return `<h2>Что выполнено сегодня?</h2><p>Добавьте одну или несколько работ. Плановые значения скрыты согласно вашей роли.</p><div class="entry-list" id="fact-list">${state.draft.facts.map((f,i)=>factRow(f,i)).join('')}</div><button class="add-link" data-action="add-fact">＋ Добавить выполненную работу</button>${reportActions()}`;
    const units=[...new Set(state.works.map(work=>work.unit).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ru'));
    const rows=state.works.map(reportWorkRow).join('');
    const textFilter=(key,label,placeholder='Найти')=>`<details class="report-column-filter"><summary aria-label="Фильтр: ${label}" title="Фильтр">⌄</summary><div class="report-filter-menu"><label>${label}<input data-report-column-filter="${key}" placeholder="${placeholder}"></label><button type="button" data-report-clear-column="${key}">Очистить</button></div></details>`;
    const numberFilter=(key,label)=>`<details class="report-column-filter"><summary aria-label="Фильтр: ${label}" title="Фильтр">⌄</summary><div class="report-filter-menu"><label>Показать значения от<input data-report-column-filter="${key}" type="number" min="0" step="any" placeholder="0"></label><button type="button" data-report-clear-column="${key}">Очистить</button></div></details>`;
    const unitFilter=`<details class="report-column-filter"><summary aria-label="Фильтр по единице измерения" title="Фильтр">⌄</summary><div class="report-filter-menu"><label>Единица измерения<select data-report-column-filter="unit"><option value="">Все</option>${units.map(unit=>`<option value="${esc(unit)}">${esc(unit)}</option>`).join('')}</select></label><button type="button" data-report-clear-column="unit">Очистить</button></div></details>`;
    const todayFilter=`<details class="report-column-filter"><summary aria-label="Фильтр по объёму за сегодня" title="Фильтр">⌄</summary><div class="report-filter-menu"><label>Заполнение<select data-report-column-filter="today"><option value="">Все строки</option><option value="filled">Заполнено</option><option value="empty">Не заполнено</option></select></label><button type="button" data-report-clear-column="today">Очистить</button></div></details>`;
    return `<div class="report-work-head"><div><h2>Выполненные работы за сегодня</h2></div><div class="report-work-meta"><span class="report-work-count" data-report-work-count>${state.works.length} работ</span><button type="button" class="report-clear-filters" data-report-clear-filters>Сбросить фильтры</button></div></div><div class="report-top-actions"><button type="button" class="button button--secondary" data-report-no-facts>Нет выполненных объёмов</button><button type="button" class="button button--secondary button--no-work" data-report-no-work>Сегодня не работали</button><span></span><button type="button" class="button button--primary" data-report-next>Продолжить →</button></div><div class="table-wrap report-work-table-wrap"><table class="data-table report-work-table"><thead><tr><th><div class="report-column-head"><span>Наименование работы</span>${textFilter('name','Наименование работы')}</div></th><th><div class="report-column-head"><span>Шифр проекта</span>${textFilter('code','Шифр проекта')}</div></th><th><div class="report-column-head"><span>Ед. изм.</span>${unitFilter}</div></th><th class="num"><div class="report-column-head"><span>Объём по договору</span>${numberFilter('contract','Объём по договору')}</div></th><th class="num"><div class="report-column-head"><span>Уже выполнено</span>${numberFilter('actual','Уже выполнено')}</div></th><th class="num"><div class="report-column-head"><span>За отчётный месяц</span>${numberFilter('month','За отчётный месяц')}</div></th><th><div class="report-column-head"><span>За сегодня</span>${todayFilter}</div></th></tr></thead><tbody>${rows||'<tr><td colspan="7" class="admin-empty-row">Для вашей организации работы не найдены</td></tr>'}</tbody></table></div>`;
  }
  function factRow(f,i){const w=state.works.find(x=>x.id===f.workId);return `<div class="entry-row"><label>Работа<select data-kind="fact-work" data-index="${i}"><option value="">Выберите работу</option>${state.works.map(x=>`<option value="${x.id}" ${x.id===f.workId?'selected':''}>${esc(x.name)} · остаток ${fmt(x.remaining,1)} ${esc(x.unit)}</option>`).join('')}</select></label><label>Выполнено сегодня<div class="amount-field"><input data-kind="fact-amount" data-index="${i}" type="number" min="0" max="${w?.remaining||''}" step="0.1" value="${esc(f.amount)}" placeholder="0"><span>${esc(w?.unit||'')}</span></div></label><button class="remove-row" data-remove="facts" data-index="${i}" aria-label="Удалить">×</button></div>`;}
  function reportWorkRow(work){const fact=state.draft.facts.find(item=>item.workId===work.id),amount=fact?.amount||'';return `<tr data-report-work-row data-report-name="${esc(`${work.name} ${(work.hierarchy||[]).join(' ')}`.toLowerCase())}" data-report-code="${esc(String(work.code||'').toLowerCase())}" data-report-unit="${esc(work.unit||'')}" data-report-contract="${Number(work.totalVolume)||0}" data-report-actual="${Number(work.accumulatedActual)||0}" data-report-month="${Number(work.monthActual)||0}" data-report-filled="${Number(amount)>0?'true':'false'}"><td><div class="work-name"><b>${esc(work.name)}</b>${work.hierarchy?.length?`<small>${esc(work.hierarchy.join(' · '))}</small>`:''}</div></td><td><b>${esc(work.code||'—')}</b></td><td>${esc(work.unit||'—')}</td><td class="num">${fmt(work.totalVolume,2)}</td><td class="num">${fmt(work.accumulatedActual,2)}</td><td class="num">${fmt(work.monthActual,2)}</td><td><div class="report-today-amount"><input data-report-work-amount="${esc(work.id)}" type="number" min="0" max="${work.remaining}" step="0.01" value="${esc(amount)}" placeholder="0"><span>${esc(work.unit||'')}</span></div><small>Остаток: ${fmt(work.remaining,2)}</small></td></tr>`;}
  function filterReportWorks(){const filters=$$('[data-report-column-filter]'),values=Object.fromEntries(filters.map(input=>[input.dataset.reportColumnFilter,String(input.value||'').trim().toLowerCase()])),rows=$$('[data-report-work-row]');for(const input of filters)input.closest('.report-column-filter')?.classList.toggle('active',Boolean(input.value));let visible=0;for(const row of rows){const filled=row.dataset.reportFilled==='true',show=(!values.name||row.dataset.reportName.includes(values.name))&&(!values.code||row.dataset.reportCode.includes(values.code))&&(!values.unit||row.dataset.reportUnit.toLowerCase()===values.unit)&&(!values.contract||Number(row.dataset.reportContract)>=Number(values.contract))&&(!values.actual||Number(row.dataset.reportActual)>=Number(values.actual))&&(!values.month||Number(row.dataset.reportMonth)>=Number(values.month))&&(!values.today||values.today==='filled'&&filled||values.today==='empty'&&!filled);row.classList.toggle('hidden',!show);if(show)visible++;}const count=$('[data-report-work-count]');if(count)count.textContent=`${visible} из ${rows.length} работ`;}
  function reportRows(key,label,countLabel,suggestions){const rows=state.draft[key];if(!rows.length)rows.push({name:'',count:''});return `<h2>${key==='workers'?'Кто работал на объекте?':'Какая техника работала?'}</h2><p>${key==='workers'?'Укажите профессии и численность сотрудников.':'Укажите виды и количество техники.'}</p><div class="entry-list">${rows.map((r,i)=>`<div class="entry-row"><label>${label}<input list="${key}-list" data-kind="${key}-name" data-index="${i}" value="${esc(r.name)}" placeholder="Начните вводить"></label><label>${countLabel}<input data-kind="${key}-count" data-index="${i}" type="number" min="1" step="1" value="${esc(r.count)}" placeholder="0"></label><button class="remove-row" data-remove="${key}" data-index="${i}">×</button></div>`).join('')}</div><datalist id="${key}-list">${suggestions.map(x=>`<option value="${esc(x)}">`).join('')}</datalist><button class="add-link" data-action="add-${key}">＋ Добавить строку</button>${reportActions()}`;}
  function reportPhotos(){return `<h2>Фотографии с объекта</h2><p>Прикрепите до 10 фото. Они относятся ко всему ежедневному отчёту.</p><div class="dropzone" id="dropzone"><input id="photo-input" type="file" accept="image/*" capture="environment" multiple><div><div class="dropzone-icon">▧</div><b>Перетащите фото или нажмите сюда</b><span>JPG, PNG · до 10 файлов</span></div></div><div class="photo-grid">${state.draft.photos.map((p,i)=>`<div class="photo"><img src="${p.dataUrl}" alt="${esc(p.name)}"><button data-remove-photo="${i}">×</button></div>`).join('')}</div>${reportActions()}`;}
  function reportReview(){const d=state.draft,settings=reportSettings(),facts=d.facts.filter(f=>f.workId&&Number(f.amount)>0),emptyText=d.noWork?'Сегодня не работали':d.noFacts?'Выполненных объёмов нет':'Не указаны';return `<h2>Проверьте отчёт</h2><p>После отправки данные сразу попадут в аналитику.</p><div class="summary-section"><h4>Выполненные работы</h4>${facts.map(f=>{const w=state.works.find(x=>x.id===f.workId);return `<div class="summary-line"><span>${esc(w?.name)}</span><b>${fmt(f.amount,1)} ${esc(w?.unit)}</b></div>`}).join('')||`<span class="muted">${emptyText}</span>`}</div>${settings.workforce?`<div class="summary-section"><h4>Люди</h4>${d.workers.map(r=>`<div class="summary-line"><span>${esc(r.name)}</span><b>${fmt(r.count)}</b></div>`).join('')||'<span class="muted">Не указаны</span>'}</div>`:''}${settings.machinery?`<div class="summary-section"><h4>Механизмы</h4>${d.equipment.map(r=>`<div class="summary-line"><span>${esc(r.name)}</span><b>${fmt(r.count)}</b></div>`).join('')||'<span class="muted">Не указаны</span>'}</div>`:''}${settings.photos!==false?`<div class="summary-section"><h4>Фото</h4><b>${d.photos.length} файлов</b></div>`:''}${reportActions(true)}`;}
  function reportActions(final=false){return `<div class="report-actions"><button class="button button--secondary" data-report-prev ${state.draft.step===0?'disabled':''}>← Назад</button><button class="button button--primary" ${final?'data-submit-report':'data-report-next'}>${final?'Отправить отчёт ✓':'Продолжить →'}</button></div>`;}
  function reportSummary(){const d=state.draft,settings=reportSettings(),workers=d.workers.reduce((s,r)=>s+Number(r.count||0),0),equipment=d.equipment.reduce((s,r)=>s+Number(r.count||0),0),flow=reportFlow(),facts=d.facts.filter(f=>f.workId&&Number(f.amount)>0),workStatus=d.noWork?'Сегодня не работали':d.noFacts?'Объёмов нет':`${facts.length} заполнено`;return `<aside class="card report-summary"><div class="card-head"><div><h3>Ваш отчёт</h3><p>${formatDate(today)}</p></div><span class="status-pill wait">Черновик</span></div><div class="summary-body"><div class="summary-section"><h4>Работы</h4><div class="summary-line"><span>За сегодня</span><b>${workStatus}</b></div></div>${settings.workforce?`<div class="summary-section"><div class="summary-line"><span>Людей</span><b>${workers}</b></div></div>`:''}${settings.machinery?`<div class="summary-section"><div class="summary-line"><span>Механизмов</span><b>${equipment}</b></div></div>`:''}${settings.photos!==false?`<div class="summary-section"><div class="summary-line"><span>Фотографий</span><b>${d.photos.length}</b></div></div>`:''}</div><div class="summary-total"><span>Готовность</span><strong>${Math.round((d.step+1)/flow.length*100)}%</strong></div></aside>`;}

  function bindReportInputs(){
    $$('[data-kind]').forEach(el=>el.addEventListener('input',()=>{const [key,field]=el.dataset.kind.split('-');const target=key==='fact'?state.draft.facts:key==='workers'?state.draft.workers:state.draft.equipment;target[Number(el.dataset.index)][field==='work'?'workId':field]=el.value;}));
    $$('[data-report-work-amount]').forEach(input=>input.addEventListener('input',()=>{const workId=input.dataset.reportWorkAmount,value=input.value,index=state.draft.facts.findIndex(item=>item.workId===workId);if(Number(value)>0){if(index>=0)state.draft.facts[index].amount=value;else state.draft.facts.push({workId,amount:value});state.draft.noFacts=false;state.draft.noWork=false;}else if(index>=0)state.draft.facts.splice(index,1);input.closest('[data-report-work-row]').dataset.reportFilled=Number(value)>0?'true':'false';filterReportWorks();}));
    $$('.report-column-filter').forEach(details=>details.addEventListener('toggle',()=>{if(details.open)$$('.report-column-filter').filter(item=>item!==details).forEach(item=>item.removeAttribute('open'));}));$$('[data-report-column-filter]').forEach(input=>{input.addEventListener('input',filterReportWorks);input.addEventListener('change',filterReportWorks);});$$('[data-report-clear-column]').forEach(button=>button.addEventListener('click',()=>{const input=$(`[data-report-column-filter="${button.dataset.reportClearColumn}"]`);if(input)input.value='';button.closest('details')?.removeAttribute('open');filterReportWorks();}));$('[data-report-clear-filters]')?.addEventListener('click',()=>{$$('[data-report-column-filter]').forEach(input=>{input.value=''});$$('.report-column-filter').forEach(details=>details.removeAttribute('open'));filterReportWorks();});
    const input=$('#photo-input'); if(input) input.addEventListener('change',()=>addPhotos(input.files));
  }
  async function addPhotos(files){for(const file of [...files].slice(0,10-state.draft.photos.length)){if(!file.type.startsWith('image/'))continue;const dataUrl=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(file)});state.draft.photos.push({name:file.name,type:file.type,dataUrl});}renderReport();}
  function validateReportFacts(){const d=state.draft,valid=d.facts.filter(f=>f.workId&&Number(f.amount)>0);if(!valid.length&&!d.noFacts&&!d.noWork)return 'Укажите объём за сегодня или выберите «Нет выполненных объёмов»';for(const f of valid){const w=state.works.find(x=>x.id===f.workId);if(!w)return 'Одна из выбранных работ недоступна';if(Number(f.amount)>w.remaining)return `Объём по работе «${w.name}» превышает остаток ${w.remaining} ${w.unit}`;}return '';}
  function validateStep(){return state.draft.step===0?validateReportFacts():'';}
  async function submitReport(options={}){const error=options.skipValidation?'':validateReportFacts();if(error)return toast(error,'error');const button=options.button||$('[data-submit-report]'),submittedNoWork=state.draft.noWork;if(button){button.disabled=true;button.textContent='Отправляем…';}try{await api('/api/reports',{method:'POST',body:JSON.stringify({projectId:state.projectId,reportDate:projectToday(),...state.draft})});state.draft={step:0,facts:[],workers:[],equipment:[],photos:[],noFacts:false,noWork:false};toast(submittedNoWork?'Отмечено: сегодня не работали':'Отчёт отправлен. Данные уже доступны руководителю.');navigate('home');}catch(e){if(button){button.disabled=false;button.textContent=options.noWork?'Сегодня не работали':'Отправить отчёт ✓';}toast(e.message,'error');}}

  async function renderReports() {
    await loadCore();
    $('#content').innerHTML=`${pageHead(state.route==='history'?'История моих отчётов':'Ежедневные отчёты',state.route==='history'?'Все отправленные вами данные':'Отчёты подрядчиков по выбранному объекту',state.role!=='responsible'?'<button class="button button--primary" data-action="admin-report">＋ Внести отчёт</button>':'')}<section class="card"><div class="card-head"><div><h3>Журнал отчётов</h3><p>${state.reports.length} записей</p></div></div>${reportsTable(state.reports,false)}</section>`;
  }
  function reportsTable(rows,compact){if(!rows.length)return `<div class="empty"><div><div class="empty-icon">▤</div><h3>Отчётов пока нет</h3><p>Первый отправленный отчёт появится здесь.</p></div></div>`;return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Дата</th>${compact?'':'<th>Подрядчик</th><th>Ответственный</th>'}<th class="num">Работ</th><th class="num">Людей</th><th class="num">Техники</th><th>Статус</th></tr></thead><tbody>${rows.map(r=>{const status=r.noWork?'Сегодня не работали':r.noFacts?'Нет объёмов':'Отправлен';return `<tr><td><b>${formatDate(r.reportDate,{day:'2-digit',month:'short',year:'numeric'})}</b><br><small class="muted">${new Date(r.sentAt).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</small></td>${compact?'':`<td>${esc(r.organization?.shortName||org(r.organizationId)?.shortName||'—')}</td><td>${esc(r.user?.name||'—')}</td>`}<td class="num">${r.facts.length}</td><td class="num">${r.workers.reduce((s,x)=>s+Number(x.count),0)}</td><td class="num">${r.equipment.reduce((s,x)=>s+Number(x.count),0)}</td><td><span class="status-pill ${r.noWork||r.noFacts?'neutral':'ok'}">● ${status}</span></td></tr>`}).join('')}</tbody></table></div>`;}

  async function renderResources(){await loadCore();const workers={},equipment={};for(const r of state.reports){for(const x of r.workers)workers[x.name]=(workers[x.name]||0)+Number(x.count);for(const x of r.equipment)equipment[x.name]=(equipment[x.name]||0)+Number(x.count)}const cards=(obj,unit)=>Object.entries(obj).sort((a,b)=>b[1]-a[1]).map(([name,count])=>`<article class="card mini-card"><div class="mini-card-head"><div><h3>${esc(name)}</h3><p>За все отчётные дни</p></div><span class="kpi-icon">${unit==='чел.'?'♙':'♜'}</span></div><div class="mini-stat"><strong>${fmt(count)}</strong><span>${unit}</span></div></article>`).join('');$('#content').innerHTML=`${pageHead('Люди и техника','Сводка ресурсов по ежедневным отчётам')}<div class="card-head" style="padding-left:0;border:0"><div><h3>Персонал</h3><p>Распределение по профессиям</p></div></div><div class="list-grid">${cards(workers,'чел.')}</div><div class="card-head" style="padding-left:0;border:0;margin-top:15px"><div><h3>Техника</h3><p>Распределение по видам</p></div></div><div class="list-grid">${cards(equipment,'ед.')}</div>`;}
  async function renderPhotos(){await loadCore();const photos=state.reports.flatMap(r=>r.photos.map(p=>({...p,report:r})));$('#content').innerHTML=`${pageHead('Фотографии','Фотофиксация с площадки по датам и подрядчикам')}${photos.length?`<div class="photo-grid" style="grid-template-columns:repeat(auto-fill,minmax(220px,1fr))">${photos.map(p=>`<div class="card" style="overflow:hidden"><img src="${p.dataUrl}" style="width:100%;aspect-ratio:4/3;object-fit:cover" alt="Фото"><div style="padding:12px"><b>${formatDate(p.report.reportDate)}</b><p class="muted" style="margin:4px 0 0;font-size:10px">${esc(org(p.report.organizationId)?.shortName||'')}</p></div></div>`).join('')}</div>`:`<div class="card empty"><div><div class="empty-icon">▧</div><h3>Фотографий пока нет</h3><p>Фото из ежедневных отчётов будут собраны здесь.</p></div></div>`}`;}

  async function renderMilestones(){const data=await api(`/api/milestones?projectId=${state.projectId}`);$('#content').innerHTML=`${pageHead('Контрольные вехи','Срез накопительного плана и факта на выбранную дату','<button class="button button--primary" data-action="new-milestone">＋ Создать веху</button>')}<div class="list-grid">${data.milestones.map(m=>{const delta=m.snapshot.cumulativeActual-m.snapshot.cumulativePlan;return `<article class="card mini-card"><div class="mini-card-head"><div><h3>${esc(m.name)}</h3><p>${formatDate(m.date)}</p></div><span class="status-pill ${delta>=0?'ok':'lag'}">${delta>=0?'В графике':'Отставание'}</span></div><div class="mini-stat"><strong>${fmt(m.snapshot.cumulativeActual,1)}</strong><span>факт / ${fmt(m.snapshot.cumulativePlan,1)} план</span></div><p class="${delta<0?'delta-negative':'delta-positive'}" style="margin-top:11px">${delta>0?'+':''}${fmt(delta,1)} отклонение</p></article>`}).join('')||'<div class="card empty"><div><h3>Вех пока нет</h3></div></div>'}</div>`;}

  async function renderSchedules(){const data=await api(`/api/schedules?projectId=${state.projectId}`),mapping=data.importMapping||defaultImportMapping,columns={...defaultImportMapping.columns,...(mapping.columns||{})};state.uploadHierarchy=[...(mapping.hierarchyColumns||defaultImportMapping.hierarchyColumns)];const hierarchy=state.uploadHierarchy.map((column,index)=>`<div class="hierarchy-row"><label class="field">Уровень ${index+1}<input data-hierarchy-index="${index}" value="${esc(column)}" placeholder="C"></label><button type="button" class="remove-row" data-remove-hierarchy="${index}" aria-label="Удалить уровень">×</button></div>`).join('');$('#content').innerHTML=`${pageHead('Загрузка таблицы','Загрузите новый план или обновите существующий месяц без потери отчётных объёмов')}<form id="schedule-import-form" class="import-layout"><section class="card upload-card"><div class="import-section-head"><span>1</span><div><h2>Файл и диапазон</h2><p>Поддерживаются XLSX и XLSB. При повторной загрузке месяца данные синхронизируются, а внесённый факт сохраняется.</p></div></div><div class="mapping-grid mapping-grid--base"><label class="field">Месяц плана<input name="month" type="month" value="${today.slice(0,7)}" required></label><label class="field">Excel-файл<input name="file" type="file" accept=".xlsx,.xlsb" required></label><label class="field">Лист<input name="sheet" value="${esc(mapping.sheet)}" placeholder="Например, СМГ" required></label><label class="field">Данные начинаются со строки<input name="dataStartRow" type="number" min="1" value="${Number(mapping.dataStartRow)||3}" required></label></div></section><section class="card upload-card"><div class="import-section-head"><span>2</span><div><h2>Основные колонки</h2><p>Вводите буквы Excel-колонок. Поля со звёздочкой обязательны.</p></div></div><div class="mapping-grid">${mappingField('number','№ работы',columns.number)}${mappingField('code','Код работы',columns.code)}${mappingField('name','Наименование работы *',columns.name,true)}${mappingField('organization','Организация *',columns.organization,true)}${mappingField('unit','Ед. изм.',columns.unit)}${mappingField('total','Объём по проекту',columns.total)}${mappingField('priorActual','Выполнено до месяца',columns.priorActual)}${mappingField('remaining','Остаток',columns.remaining)}${mappingField('monthlyPlan','План на месяц',columns.monthlyPlan)}</div></section><section class="card upload-card"><div class="import-section-head"><span>3</span><div><h2>Структура работ</h2><p>Добавьте сколько угодно уровней: блок, подблок, этап и т.д.</p></div></div><div id="hierarchy-fields" class="hierarchy-fields">${hierarchy}</div><button type="button" class="add-link" data-action="add-hierarchy">＋ Добавить уровень</button></section><section class="card upload-card"><div class="import-section-head"><span>4</span><div><h2>План по дням и строка факта</h2><p>В примере план и факт идут парой строк, а дни месяца начинаются с колонки O.</p></div></div><div class="mapping-grid">${mappingField('rowType','Признак «План/Факт»',columns.rowType)}${mappingField('firstDay','Первый день месяца *',columns.firstDay,true)}<label class="field">Значение строки плана<input name="planRowValue" value="${esc(mapping.planRowValue)}"></label><label class="field">Строка факта через<input name="factRowOffset" type="number" min="0" value="${Number(mapping.factRowOffset)||0}"></label></div></section><div class="import-submit"><button class="button button--primary" type="submit">Загрузить или обновить таблицу</button><p class="muted" id="mapping-save-status">Настройки источника сохраняются автоматически для этого объекта.</p></div></form><section class="card" style="margin-top:20px"><div class="card-head"><div><h3>Загруженные таблицы</h3><p>${data.schedules.length} версий</p></div></div><div class="card-pad schedule-list">${scheduleItems(data.schedules)}</div></section>`;}
  function mappingField(name,label,value,required=false){return `<label class="field">${label}<input name="${name}" value="${value}" placeholder="Буква колонки" ${required?'required':''}></label>`;}
  function importMappingFromForm(form){const fd=new FormData(form),columnNames=['number','code','name','organization','unit','total','priorActual','remaining','monthlyPlan','rowType','firstDay'];return{sheet:String(fd.get('sheet')||'').trim(),dataStartRow:Number(fd.get('dataStartRow')),hierarchyColumns:state.uploadHierarchy.filter(Boolean),columns:Object.fromEntries(columnNames.map(name=>[name,String(fd.get(name)||'').trim().toUpperCase()])),planRowValue:String(fd.get('planRowValue')||'План'),factRowOffset:Number(fd.get('factRowOffset')||0)};}
  function queueImportMappingSave(){const form=$('#schedule-import-form');if(!form)return;const projectId=state.projectId,mapping=importMappingFromForm(form),status=$('#mapping-save-status');if(status)status.textContent='Сохраняем настройки источника…';clearTimeout(scheduleMappingSaveTimer);scheduleMappingSaveTimer=setTimeout(async()=>{try{await api('/api/schedules/mapping',{method:'POST',body:JSON.stringify({projectId,mapping})});if(state.projectId===projectId&&$('#mapping-save-status'))$('#mapping-save-status').textContent='Настройки источника сохранены для этого объекта.';}catch(error){if(state.projectId===projectId&&$('#mapping-save-status'))$('#mapping-save-status').textContent=`Не удалось сохранить настройки: ${error.message}`;}},500);}
  function scheduleItems(items){return items.map(s=>`<div class="schedule-item"><div class="file-icon">X</div><div><b>${esc(s.originalName)}</b><small>${formatDate(s.month+'-01',{month:'long',year:'numeric'})} · версия ${s.version} · ${formatDate(s.uploadedAt.slice(0,10))}</small></div><span class="status-pill ${s.status==='active'?'ok':''}">${s.status==='active'?'Активен':'Архив'}</span><div class="schedule-actions"><a class="button button--secondary button--small" href="${apiPath(`/api/schedules/${s.id}/json`)}">JSON</a>${s.storedName?`<a class="button button--secondary button--small" href="${apiPath(`/api/schedules/${s.id}/original`)}">Исходник</a><a class="button button--ghost button--small" href="${apiPath(`/api/schedules/${s.id}/export`)}">План / Факт</a>`:''}</div></div>`).join('')||'<p class="muted">Графики ещё не загружены.</p>';}
  async function uploadSchedule(form){const fd=new FormData(form),file=fd.get('file'),button=form.querySelector('button[type="submit"]');if(!file?.name)return toast('Выберите Excel-файл','error');clearTimeout(scheduleMappingSaveTimer);button.disabled=true;button.textContent='Читаем таблицу…';try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});const mapping=importMappingFromForm(form);const data=await api('/api/schedules/import',{method:'POST',body:JSON.stringify({projectId:state.projectId,month:fd.get('month'),fileName:file.name,base64,mapping})}),summary=data.updateSummary||{};toast(`Таблица обновлена: добавлено ${summary.added||0}, обновлено ${summary.updated||0}, удалено ${summary.removed||0}${summary.retainedWithFacts?`, сохранено с отчётом ${summary.retainedWithFacts}`:''}`);renderSchedules();}catch(error){button.disabled=false;button.textContent='Загрузить или обновить таблицу';toast(error.message,'error');}}
  async function renderArchive(){const data=await api(`/api/schedules?projectId=${state.projectId}`);const groups={};for(const s of data.schedules){const year=s.month.slice(0,4);(groups[year]??=[]).push(s)}$('#content').innerHTML=`${pageHead('Архив графиков','История месяцев, исходных файлов и фактических данных')}${Object.entries(groups).sort((a,b)=>b[0]-a[0]).map(([year,items])=>`<section class="card" style="margin-bottom:14px"><div class="card-head"><div><h3>${year}</h3><p>${items.length} версий графиков</p></div></div><div class="card-pad schedule-list">${scheduleItems(items)}</div></section>`).join('')}`;}

  async function renderExport(){const data=await api(`/api/schedules?projectId=${state.projectId}`);$('#content').innerHTML=`${pageHead('Выгрузка План / Факт','Скачайте версию таблицы с накопленными фактическими объёмами')}<section class="card"><div class="card-head"><div><h3>Доступные выгрузки</h3><p>${data.schedules.length} версий</p></div></div><div class="card-pad schedule-list">${data.schedules.map(s=>`<div class="schedule-item"><div class="file-icon">X</div><div><b>${esc(s.originalName)}</b><small>${formatDate(s.month+'-01',{month:'long',year:'numeric'})} · версия ${s.version}</small></div><span class="status-pill ${s.status==='active'?'ok':''}">${s.status==='active'?'Активен':'Архив'}</span>${s.storedName?`<a class="button button--primary button--small" href="${apiPath(`/api/schedules/${s.id}/export`)}">Скачать План / Факт</a>`:''}</div>`).join('')||'<div class="empty"><div><h3>Нет таблиц для выгрузки</h3><p>Сначала загрузите Excel-файл.</p></div></div>'}</div></section>`;}

  async function renderAnalysis(){await loadCore();$('#content').innerHTML=`${pageHead('Анализ','Здесь будет собрана вся информация по работам')}<section class="card empty"><div><div class="empty-icon">◫</div><h3>Раздел готовится</h3><p>Уже загружено работ: <b>${state.works.length}</b>. Здесь появятся сводки, статусы и отклонения.</p></div></section>`;}

  async function renderAdministration(){const d=await adminData(),project=d.projects.find(item=>item.id===state.projectId)||state.projects.find(item=>item.id===state.projectId),tab=state.adminTab||'projects';state.adminSnapshot=d;$('#content').innerHTML=`<section class="admin-hero card"><div class="admin-hero-copy"><p class="admin-kicker">Администрирование</p><h1>${esc(project?.name||'Текущий объект')}</h1><div class="admin-meta"><span class="status-pill ${project?.status==='archive'?'neutral':'ok'}">${project?.status==='archive'?'Архив':'Активен'}</span><span>ID: ${esc(project?.id||'—')}</span><span>Объекты</span></div></div><label class="admin-object-select"><span>Объект администрирования</span><select data-admin-project>${d.projects.map(item=>`<option value="${item.id}" ${item.id===state.projectId?'selected':''}>${esc(item.name)}</option>`).join('')}</select></label></section><section class="admin-tabs card"><div>${[['projects','Объекты'],['organizations','Организации'],['users','Пользователи'],['telegram','Telegram-чаты']].map(([id,label])=>`<button class="${tab===id?'active':''}" data-admin-tab="${id}">${label}</button>`).join('')}</div><select aria-label="Режим"><option>Управление</option></select></section>${adminTabContent(d,tab)}`;filterAdminRows();}
  function adminTabContent(d,tab){const organizations=d.organizations.filter(item=>item.projectIds.includes(state.projectId));if(tab==='organizations')return adminPanel('Организации',`${organizations.length} для текущего объекта`,'new-organization','Добавить организацию',`<table class="data-table admin-data-table"><thead><tr><th>Организация</th><th>Статус</th><th>Состав ежедневного отчёта</th></tr></thead><tbody>${organizations.map(o=>{const settings=o.reportSettings||{planFact:true,workforce:false,machinery:false};return `<tr data-admin-row data-admin-status="active" data-admin-search="${esc(`${o.shortName} ${o.fullName}`.toLowerCase())}"><td><div class="admin-object-cell"><span class="admin-row-icon">${esc((o.shortName||'О').slice(0,1))}</span><span><b>${esc(o.shortName)}</b><small>${esc(o.fullName)}</small></span></div></td><td><span class="status-pill ok">Активна</span></td><td><div class="admin-inline-settings"><label><input type="checkbox" data-org-setting="planFact" data-org-id="${o.id}" ${settings.planFact?'checked':''} disabled> План / Факт</label><label><input type="checkbox" data-org-setting="workforce" data-org-id="${o.id}" ${settings.workforce?'checked':''}> Люди</label><label><input type="checkbox" data-org-setting="machinery" data-org-id="${o.id}" ${settings.machinery?'checked':''}> Механизмы</label></div></td></tr>`}).join('')||adminEmptyRow(3,'Организаций пока нет')}</tbody></table>`);if(tab==='users')return adminPanel('Пользователи',`${d.users.length} учётных записей`,'new-user','Добавить пользователя',`<table class="data-table admin-data-table"><thead><tr><th>Пользователь</th><th>Организация</th><th>Логин</th><th>Telegram ID</th><th>Доступ</th></tr></thead><tbody>${d.users.map(u=>`<tr data-admin-row data-admin-status="active" data-admin-search="${esc(`${u.name} ${u.login} ${u.telegramId||''}`.toLowerCase())}"><td><div class="admin-object-cell"><span class="avatar--small">${initials(u.name)}</span><span><b>${esc(u.name)}</b><small>Пользователь системы</small></span></div></td><td>${esc(u.organization?.fullName||'Не указана')}</td><td>${esc(u.login)}</td><td>${esc(u.telegramId||'Не привязан')}</td><td>${u.assignments.map(a=>`<span class="org-pill">${esc(d.projects.find(p=>p.id===a.projectId)?.shortName)} · ${roleNames[a.role]}</span>`).join(' ')}</td></tr>`).join('')||adminEmptyRow(5,'Пользователей пока нет')}</tbody></table>`);if(tab==='telegram')return adminPanel('Telegram-чаты',`${d.users.filter(u=>u.telegramId).length} привязанных аккаунтов`,'','','<table class="data-table admin-data-table"><thead><tr><th>Пользователь</th><th>Telegram ID</th><th>Статус</th><th>Объекты</th></tr></thead><tbody>'+d.users.filter(u=>u.telegramId).map(u=>`<tr data-admin-row data-admin-status="active" data-admin-search="${esc(`${u.name} ${u.telegramId}`.toLowerCase())}"><td><b>${esc(u.name)}</b></td><td>${esc(u.telegramId)}</td><td><span class="status-pill ok">Привязан</span></td><td>${u.assignments.map(a=>esc(d.projects.find(p=>p.id===a.projectId)?.shortName)).join(', ')}</td></tr>`).join('')+`${d.users.some(u=>u.telegramId)?'':adminEmptyRow(4,'Привязанных Telegram-аккаунтов пока нет')}</tbody></table>`);return adminPanel('Объекты',`${d.projects.length} в системе`,'new-project','Добавить объект',`<table class="data-table admin-data-table"><thead><tr><th>Объект</th><th>Ответственный</th><th>Статус</th><th>Доступ</th><th></th></tr></thead><tbody>${d.projects.map(p=>{const owner=d.users.find(u=>u.assignments.some(a=>a.projectId===p.id&&a.role==='admin'));return `<tr class="${p.id===state.projectId?'current':''}" data-admin-row data-admin-status="${p.status||'active'}" data-admin-search="${esc(`${p.name} ${p.shortName} ${p.id}`.toLowerCase())}"><td><div class="admin-object-cell"><span class="admin-row-icon">${p.id===state.projectId?'«':esc((p.shortName||'О').slice(0,1))}</span><span><b>${esc(p.name)}</b><small>${esc(p.shortName)}${p.id===state.projectId?' · Текущий':''}</small></span></div></td><td>${esc(owner?.name||'Не назначен')}</td><td><span class="status-pill ${p.status==='active'?'ok':'neutral'}">${p.status==='active'?'Активен':'Архив'}</span></td><td>${p.contractorIds?.length||0} организаций</td><td><button class="button button--secondary button--small" data-admin-open-project="${p.id}">${p.id===state.projectId?'Открыт':'Перейти'}</button></td></tr>`}).join('')||adminEmptyRow(5,'Объектов пока нет')}</tbody></table>`);}
  function adminPanel(title,subtitle,action,label,table){return `<section class="admin-panel card"><div class="admin-panel-head"><div><h2>${title}</h2><p>${subtitle}</p></div>${action?`<button class="button button--primary" data-action="${action}">＋ ${label}</button>`:''}</div><div class="admin-toolbar"><label class="admin-search"><span>⌕</span><input data-admin-search-input placeholder="Найти: название, ID или ответственный"></label><label class="admin-status-filter"><span>Статус</span><select data-admin-status-filter><option value="all">Все</option><option value="active">Активные</option><option value="archive">Архивные</option></select></label></div><div class="admin-table-wrap table-wrap">${table}</div><div class="admin-pagination"><span data-admin-count></span><span>Назад&nbsp;&nbsp;&nbsp; 1 / 1 &nbsp;&nbsp;&nbsp;Вперёд</span></div></section>`;}
  function adminEmptyRow(columns,message){return `<tr><td colspan="${columns}" class="admin-empty-row">${message}</td></tr>`;}
  function adminEditButton(type,id,label){return `<button type="button" class="admin-edit-button" data-admin-edit="${type}" data-admin-id="${esc(id)}" title="Редактировать ${esc(label)}" aria-label="Редактировать ${esc(label)}">✎</button>`;}
  function adminTabContent(d,tab){
    const organizations=d.organizations.filter(item=>item.projectIds.includes(state.projectId));
    if(tab==='organizations')return adminPanel('Организации',`${organizations.length} для текущего объекта`,'new-organization','Добавить организацию',`<table class="data-table admin-data-table"><thead><tr><th>Организация</th><th>Статус</th><th>Состав ежедневного отчёта</th><th><span class="visually-hidden">Действия</span></th></tr></thead><tbody>${organizations.map(o=>{const settings=o.reportSettings||{planFact:true,workforce:false,machinery:false,photos:true};return `<tr data-admin-row data-admin-status="${o.status||'active'}" data-admin-search="${esc(`${o.shortName} ${o.fullName}`.toLowerCase())}"><td><div class="admin-object-cell"><span class="admin-row-icon">${esc((o.shortName||'О').slice(0,1))}</span><span><b>${esc(o.shortName)}</b><small>${esc(o.fullName)}</small></span></div></td><td><span class="status-pill ${o.status==='archive'?'neutral':'ok'}">${o.status==='archive'?'Архив':'Активна'}</span></td><td><div class="admin-inline-settings"><label><input type="checkbox" ${settings.planFact?'checked':''} disabled> План / Факт</label><label><input type="checkbox" ${settings.workforce?'checked':''} disabled> Люди</label><label><input type="checkbox" ${settings.machinery?'checked':''} disabled> Механизмы</label><label><input type="checkbox" ${settings.photos!==false?'checked':''} disabled> Фото</label></div></td><td>${adminEditButton('organization',o.id,'организацию')}</td></tr>`}).join('')||adminEmptyRow(4,'Организаций пока нет')}</tbody></table>`);
    if(tab==='users')return adminPanel('Пользователи',`${d.users.length} учётных записей`,'new-user','Добавить пользователя',`<table class="data-table admin-data-table"><thead><tr><th>Пользователь</th><th>Организация</th><th>Логин</th><th>Telegram ID</th><th>Доступ</th><th><span class="visually-hidden">Действия</span></th></tr></thead><tbody>${d.users.map(u=>`<tr data-admin-row data-admin-status="${u.status||'active'}" data-admin-search="${esc(`${u.name} ${u.login} ${u.telegramId||''}`.toLowerCase())}"><td><div class="admin-object-cell"><span class="avatar--small">${initials(u.name)}</span><span><b>${esc(u.name)}</b><small><span class="status-pill ${u.status==='archive'?'neutral':'ok'}">${u.status==='archive'?'Архив':'Активен'}</span></small></span></div></td><td>${esc(u.organization?.fullName||'Не указана')}</td><td>${esc(u.login)}</td><td>${esc(u.telegramId||'Не привязан')}</td><td>${u.assignments.map(a=>`<span class="org-pill">${esc(d.projects.find(p=>p.id===a.projectId)?.shortName)} · ${roleNames[a.role]}</span>`).join(' ')}</td><td>${adminEditButton('user',u.id,'пользователя')}</td></tr>`).join('')||adminEmptyRow(6,'Пользователей пока нет')}</tbody></table>`);
    if(tab==='telegram')return adminPanel('Telegram-чаты',`${d.users.filter(u=>u.telegramId).length} привязанных аккаунтов`,'','','<table class="data-table admin-data-table"><thead><tr><th>Пользователь</th><th>Telegram ID</th><th>Статус</th><th>Объекты</th><th><span class="visually-hidden">Действия</span></th></tr></thead><tbody>'+d.users.filter(u=>u.telegramId).map(u=>`<tr data-admin-row data-admin-status="${u.status||'active'}" data-admin-search="${esc(`${u.name} ${u.telegramId}`.toLowerCase())}"><td><b>${esc(u.name)}</b></td><td>${esc(u.telegramId)}</td><td><span class="status-pill ${u.status==='archive'?'neutral':'ok'}">${u.status==='archive'?'Архив':'Привязан'}</span></td><td>${u.assignments.map(a=>esc(d.projects.find(p=>p.id===a.projectId)?.shortName)).join(', ')}</td><td>${adminEditButton('telegram',u.id,'Telegram-чат')}</td></tr>`).join('')+`${d.users.some(u=>u.telegramId)?'':adminEmptyRow(5,'Привязанных Telegram-аккаунтов пока нет')}</tbody></table>`);
    return adminPanel('Объекты',`${d.projects.length} в системе`,'new-project','Добавить объект',`<table class="data-table admin-data-table"><thead><tr><th>Объект</th><th>Ответственный</th><th>Статус</th><th>Доступ</th><th><span class="visually-hidden">Действия</span></th></tr></thead><tbody>${d.projects.map(p=>{const owner=d.users.find(u=>u.assignments.some(a=>a.projectId===p.id&&a.role==='admin'));return `<tr class="${p.id===state.projectId?'current':''}" data-admin-row data-admin-status="${p.status||'active'}" data-admin-search="${esc(`${p.name} ${p.shortName} ${p.id}`.toLowerCase())}"><td><div class="admin-object-cell"><span class="admin-row-icon">${p.id===state.projectId?'«':esc((p.shortName||'О').slice(0,1))}</span><span><b>${esc(p.name)}</b><small>${esc(p.shortName)}${p.id===state.projectId?' · Текущий':''}</small></span></div></td><td>${esc(owner?.name||'Не назначен')}</td><td><span class="status-pill ${p.status==='active'?'ok':'neutral'}">${p.status==='active'?'Активен':'Архив'}</span></td><td>${p.contractorIds?.length||0} организаций</td><td><div class="admin-row-actions"><button class="button button--secondary button--small" data-admin-open-project="${p.id}">${p.id===state.projectId?'Открыт':'Перейти'}</button>${adminEditButton('project',p.id,'объект')}</div></td></tr>`}).join('')||adminEmptyRow(5,'Объектов пока нет')}</tbody></table>`);
  }
  function filterAdminRows(){const query=String($('[data-admin-search-input]')?.value||'').trim().toLowerCase(),status=$('[data-admin-status-filter]')?.value||'all',rows=$$('[data-admin-row]');let visible=0;for(const row of rows){const show=(!query||row.dataset.adminSearch.includes(query))&&(status==='all'||row.dataset.adminStatus===status);row.classList.toggle('hidden',!show);if(show)visible++;}const count=$('[data-admin-count]');if(count)count.textContent=`Показано: ${visible} из ${rows.length}`;}
  function organizationSettingsCard(organization){const settings=organization.reportSettings||{planFact:true,workforce:false,machinery:false,photos:true};return `<article class="card org-settings-card"><div><h3>${esc(organization.shortName)}</h3><p>${esc(organization.fullName)}</p></div><div class="settings-list"><label><span><b>План / Факт</b><small>Объёмы выполненных работ</small></span><input type="checkbox" data-org-setting="planFact" data-org-id="${organization.id}" ${settings.planFact?'checked':''} disabled></label><label><span><b>Люди</b><small>Профессии и количество</small></span><input type="checkbox" data-org-setting="workforce" data-org-id="${organization.id}" ${settings.workforce?'checked':''}></label><label><span><b>Механизмы</b><small>Машины и техника</small></span><input type="checkbox" data-org-setting="machinery" data-org-id="${organization.id}" ${settings.machinery?'checked':''}></label><label><span><b>Фото</b><small>Фотофиксация с объекта</small></span><input type="checkbox" data-org-setting="photos" data-org-id="${organization.id}" ${settings.photos!==false?'checked':''}></label></div></article>`;}

  async function adminData(){return api(`/api/admin?projectId=${state.projectId}`);}
  async function refreshAdministration(message){const full=await api('/api/bootstrap');state.projects=full.projects;state.organizations=full.organizations;state.user=full.user;if(!state.projects.some(item=>item.id===state.projectId))state.projectId=state.projects[0]?.id||'';setContext();renderChrome();closeModal();await renderAdministration();toast(message);}
  async function renderProjects(){const d=await adminData();$('#content').innerHTML=`${pageHead('Объекты','Создание и управление строительными объектами','<button class="button button--primary" data-action="new-project">＋ Новый объект</button>')}<div class="list-grid">${d.projects.map(p=>`<article class="card mini-card"><div class="mini-card-head"><div><h3>${esc(p.shortName)}</h3><p>${esc(p.name)}</p></div><span class="status-pill ${p.status==='active'?'ok':''}">${p.status==='active'?'Активен':'Архив'}</span></div><p style="margin-top:12px"><b>Заказчик:</b> ${esc(p.customerOrganization?.fullName||'не указан')}<br><small>${esc(p.customerOrganization?.portalPage||'')}</small></p><div class="mini-stat"><strong>${p.contractorIds?.length ?? d.organizations.filter(o=>o.projectIds.includes(p.id)).length}</strong><span>подрядчиков</span></div><p style="margin-top:12px">${esc(p.timezone)}</p></article>`).join('')}</div>`;}
  async function renderUsers(){const d=await adminData();$('#content').innerHTML=`${pageHead('Пользователи','Роли и доступ назначаются отдельно для каждого объекта','<button class="button button--primary" data-action="new-user">＋ Новый пользователь</button>')}<section class="card">${`<div class="table-wrap"><table class="data-table"><thead><tr><th>Пользователь</th><th>Организация</th><th>Логин</th><th>Telegram ID</th><th>Доступы</th><th>Статус</th></tr></thead><tbody>${d.users.map(u=>`<tr><td><span class="avatar--small">${initials(u.name)}</span><b>${esc(u.name)}</b></td><td><b>${esc(u.organization?.fullName||'Не указана')}</b><br><small>${esc(u.organization?.customerOrganizationName||'')}</small></td><td>${esc(u.login)}</td><td>${esc(u.telegramId||'Не привязан')}</td><td>${u.assignments.map(a=>`<span class="org-pill">${esc(d.projects.find(p=>p.id===a.projectId)?.shortName)} · ${esc(a.customerOrganization?.portalName||'')} · ${roleNames[a.role]}</span>`).join(' ')}</td><td><span class="status-pill ok">Активен</span></td></tr>`).join('')}</tbody></table></div>`}</section>`;}
  async function renderOrganizations(){const d=await adminData();$('#content').innerHTML=`${pageHead('Организации','Единый справочник подрядчиков','<button class="button button--primary" data-action="new-organization">＋ Новый подрядчик</button>')}<div class="list-grid">${d.organizations.filter(o=>o.projectIds.includes(state.projectId)).map(o=>`<article class="card mini-card"><div class="mini-card-head"><div><h3>${esc(o.shortName)}</h3><p>${esc(o.fullName)}</p></div><span class="status-pill ok">Активна</span></div><div class="mini-stat"><strong>${state.works.filter(w=>w.organizationId===o.id).length}</strong><span>работ на объекте</span></div></article>`).join('')}</div>`;}
  async function renderDictionaries(){await loadCore();$('#content').innerHTML=`${pageHead('Справочники','Стандартизированные названия персонала и техники')}<div class="dashboard-grid"><section class="card"><div class="card-head"><div><h3>Профессии</h3><p>${state.dictionaries.professions.length} значений</p></div><button class="button button--small button--secondary">＋ Добавить</button></div><div class="card-pad">${state.dictionaries.professions.map(x=>`<span class="org-pill" style="margin:4px">${esc(x)}</span>`).join('')}</div></section><section class="card"><div class="card-head"><div><h3>Техника</h3><p>${state.dictionaries.equipment.length} значений</p></div><button class="button button--small button--secondary">＋ Добавить</button></div><div class="card-pad">${state.dictionaries.equipment.map(x=>`<span class="org-pill" style="margin:4px">${esc(x)}</span>`).join('')}</div></section></div>`;}
  async function renderAudit(){const d=await adminData();$('#content').innerHTML=`${pageHead('Журнал действий','Критические события и изменения данных')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Дата и время</th><th>Пользователь</th><th>Действие</th><th>Новое значение</th></tr></thead><tbody>${d.audit.map(a=>`<tr><td>${new Date(a.at).toLocaleString('ru-RU')}</td><td>${esc(a.user?.name||'Система')}</td><td><span class="audit-action">${esc(actionNames[a.action]||a.action)}</span></td><td><code style="font-size:9px">${esc(JSON.stringify(a.newValue)).slice(0,120)}</code></td></tr>`).join('')}</tbody></table></div></section>`;}
  async function renderSettings(){const project=state.projects.find(p=>p.id===state.projectId);$('#content').innerHTML=`${pageHead('Настройки','Параметры текущего объекта')}<section class="card card-pad" style="max-width:700px"><div class="form-stack"><label>Полное название объекта<input value="${esc(project.name)}"></label><label>Короткое название<input value="${esc(project.shortName)}"></label><label>Часовой пояс<select><option>${esc(project.timezone)}</option></select></label><label>Статус<select><option>Активный</option><option>Архивный</option></select></label><div><button class="button button--primary" data-action="save-settings">Сохранить изменения</button></div></div></section>`;}
  async function renderProfile(){const a=state.user.assignments.find(a=>a.projectId===state.projectId);$('#content').innerHTML=`${pageHead('Профиль','Ваши данные и текущий уровень доступа')}<section class="card card-pad" style="max-width:700px"><div style="display:flex;align-items:center;gap:15px;margin-bottom:22px"><span class="avatar" style="width:58px;height:58px;font-size:17px">${initials(state.user.name)}</span><div><h2 style="margin:0 0 5px">${esc(state.user.name)}</h2><span class="status-pill ok">${roleNames[a.role]}</span></div></div><div class="form-stack"><label>Telegram ID<input value="${esc(state.user.telegramId||'Не привязан')}" disabled></label><label>Организация пользователя<input value="${esc(a.organization?.fullName||state.user.organization?.fullName||'Не указана')}" disabled></label><label>Текущий объект<input value="${esc(state.projects.find(p=>p.id===state.projectId)?.name)}" disabled></label><label>Организация-заказчик<input value="${esc(a.customerOrganization?.portalName||'Не указана')}" disabled></label><label>Доступные подрядчики<input value="${esc(a.organizationIds.map(id=>org(id)?.shortName).filter(Boolean).join(', ')||'Нет ограничений')}" disabled></label></div></section>`;}

  function openModal(html){$('#modal-content').innerHTML=html;$('#modal').classList.remove('hidden');}
  function closeModal(){$('#modal').classList.add('hidden');}
  function milestoneModal(){openModal(`<h2>Новая контрольная веха</h2><p>Система зафиксирует накопительный план и факт на выбранную дату.</p><form id="milestone-form" class="form-stack"><label>Название<input name="name" value="Контрольный срез" required></label><label>Дата среза<input name="date" type="date" value="${today}" required></label><div class="modal-actions"><button type="button" class="button button--secondary" data-close-modal>Отмена</button><button class="button button--primary">Создать веху</button></div></form>`);}
  function calendarModal(){const a=state.analytics;const first=new Date(`${a.from}T12:00:00`);const blanks=(first.getDay()+6)%7;const cells=Array(blanks).fill('<div class="cal-empty"></div>').concat(a.days.map(d=>`<div><span class="cal-day">${d.date.slice(8)}</span><div class="cal-values"><span>П ${fmt(d.plan,1)}</span><span>Ф ${fmt(d.actual,1)}</span></div></div>`));openModal(`<h2>Календарь План / Факт</h2><p>${formatDate(a.from)} — ${formatDate(a.to)}</p><div class="calendar">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<div class="cal-head">${x}</div>`).join('')}${cells.join('')}</div>`);}
  function projectModal(){openModal(`<h2>Новый объект</h2><p>Системные параметры портала будут назначены автоматически.</p><form id="project-form" class="form-stack"><label>Полное название объекта<input name="name" required></label><label>Короткое название<input name="shortName" required></label><label>Полное название организации-заказчика<input name="customerOrganizationFullName" required></label><div class="modal-actions"><button type="button" class="button button--secondary" data-close-modal>Отмена</button><button class="button button--primary">Создать объект</button></div></form>`);}
  function organizationModal(){openModal(`<h2>Новая организация</h2><p>Организация будет привязана к текущему объекту.</p><form id="organization-form" class="form-stack"><label>Полное наименование<input name="fullName" required></label><label>Краткое наименование<input name="shortName" required></label><label class="link-confirm"><input name="workforce" type="checkbox"><span>Отчитывать людей и профессии</span></label><label class="link-confirm"><input name="machinery" type="checkbox"><span>Отчитывать механизмы и машины</span></label><label class="link-confirm"><input name="photos" type="checkbox" checked><span>Добавлять фотофиксацию</span></label><div class="modal-actions"><button type="button" class="button button--secondary" data-close-modal>Отмена</button><button class="button button--primary">Создать организацию</button></div></form>`);}
  function userModal(){const organizations=state.organizations.filter(o=>o.projectIds.includes(state.projectId));openModal(`<h2>Новый пользователь</h2><p>Роль и организация назначаются в контексте текущего объекта.</p><form id="user-form" class="form-stack"><label>Фамилия<input name="lastName" autocomplete="family-name" required></label><label>Имя<input name="firstName" autocomplete="given-name" required></label><label>Отчество<input name="middleName" autocomplete="additional-name"></label><label>Логин<input name="login" autocomplete="username" required></label><label>Пароль<input name="password" type="password" autocomplete="new-password" value="ChangeMe2026!" required></label><label>Telegram ID<input id="new-user-telegram-id" name="telegramId" inputmode="numeric" placeholder="Можно оставить пустым"></label><label class="link-confirm"><input id="new-user-telegram-invite" name="createTelegramInvite" type="checkbox" checked><span><b>Сформировать ссылку для Telegram</b><small>Отправьте её пользователю — его Telegram ID привяжется автоматически</small></span></label><label>Роль<select name="role" id="new-user-role"><option value="responsible">Ответственный</option><option value="manager">Руководитель</option><option value="admin">Администратор</option></select></label><label id="new-user-org-wrap">Организация<select name="organizationId">${organizations.map(o=>`<option value="${o.id}">${esc(o.shortName)}</option>`).join('')}</select></label><div class="modal-actions"><button type="button" class="button button--secondary" data-close-modal>Отмена</button><button class="button button--primary">Создать пользователя</button></div></form>`);$('#new-user-role').addEventListener('change',e=>$('#new-user-org-wrap').classList.toggle('hidden',e.target.value!=='responsible'));const telegramId=$('#new-user-telegram-id'),invite=$('#new-user-telegram-invite'),syncInvite=()=>{const manual=Boolean(telegramId.value.trim());invite.disabled=manual;if(manual)invite.checked=false;};telegramId.addEventListener('input',syncInvite);}
  function telegramInviteModal(invite,account){const shareUrl=`https://t.me/share/url?url=${encodeURIComponent(invite.url)}&text=${encodeURIComponent(`Привяжите Telegram к аккаунту «План / Факт» для ${account.name}`)}`;openModal(`<div class="telegram-invite-result"><div class="login-monogram">TG</div><h2>Пользователь создан</h2><p>Отправьте эту одноразовую ссылку пользователю. После открытия Telegram ID автоматически привяжется к его учётной записи.</p><label>Ссылка для привязки<div class="invite-link-row"><input id="telegram-invite-link" value="${esc(invite.url)}" readonly><button type="button" class="button button--secondary" data-copy-telegram-invite>Копировать</button></div></label><small>Ссылка действует до ${new Date(invite.expiresAt).toLocaleString('ru-RU')} и срабатывает один раз.</small><div class="modal-actions"><button type="button" class="button button--secondary" data-close-modal>Готово</button><a class="button button--primary" href="${esc(shareUrl)}" target="_blank" rel="noopener">Отправить в Telegram</a></div></div>`);}
  function editProjectModal(project){openModal(`<h2>Редактирование объекта</h2><p>ID объекта: ${esc(project.id)}</p><form id="edit-project-form" class="form-stack" data-entity-id="${esc(project.id)}"><label>Название<input name="shortName" value="${esc(project.shortName)}" required></label><label>Официальное название<input name="name" value="${esc(project.name)}" required></label><label>Полное название организации-заказчика<input name="customerOrganizationFullName" value="${esc(project.customerOrganization?.fullName||'')}" required></label><label>Статус<select name="status"><option value="active" ${project.status!=='archive'?'selected':''}>Активный</option><option value="archive" ${project.status==='archive'?'selected':''}>Архивный</option></select></label><div class="modal-actions"><button type="button" class="button button--secondary" data-close-modal>Отмена</button><button class="button button--primary">Сохранить изменения</button></div></form>`);}
  function editOrganizationModal(organization){const settings=organization.reportSettings||{};openModal(`<h2>Редактирование организации</h2><p>Изменения применятся на текущем объекте.</p><form id="edit-organization-form" class="form-stack" data-entity-id="${esc(organization.id)}"><label>Полное наименование<input name="fullName" value="${esc(organization.fullName)}" required></label><label>Краткое наименование<input name="shortName" value="${esc(organization.shortName)}" required></label><label>Статус<select name="status"><option value="active" ${organization.status!=='archive'?'selected':''}>Активная</option><option value="archive" ${organization.status==='archive'?'selected':''}>Архивная</option></select></label><label class="link-confirm"><input name="workforce" type="checkbox" ${settings.workforce?'checked':''}><span>Отчитывать людей и профессии</span></label><label class="link-confirm"><input name="machinery" type="checkbox" ${settings.machinery?'checked':''}><span>Отчитывать механизмы и машины</span></label><label class="link-confirm"><input name="photos" type="checkbox" ${settings.photos!==false?'checked':''}><span>Добавлять фотофиксацию</span></label><div class="modal-actions"><button type="button" class="button button--secondary" data-close-modal>Отмена</button><button class="button button--primary">Сохранить изменения</button></div></form>`);}
  function editUserModal(account,telegramOnly=false){const organizations=(state.adminSnapshot?.organizations||state.organizations).filter(o=>o.projectIds.includes(state.projectId)),assigned=account.assignments.find(a=>a.projectId===state.projectId)||account.assignments[0]||{},role=assigned.role||'responsible',organizationId=assigned.organizationIds?.[0]||'';openModal(`<h2>${telegramOnly?'Редактирование Telegram-чата':'Редактирование пользователя'}</h2><p>Данные и доступ пользователя можно изменить в контексте текущего объекта.</p><form id="edit-user-form" class="form-stack" data-entity-id="${esc(account.id)}"><label>ФИО<input name="name" value="${esc(account.name)}" required></label><label>Логин<input name="login" value="${esc(account.login)}" required></label><label>Новый пароль<input name="password" type="password" placeholder="Оставьте пустым, чтобы не менять"></label><label>Telegram ID<input name="telegramId" inputmode="numeric" value="${esc(account.telegramId||'')}"></label><label>Роль<select name="role" id="edit-user-role"><option value="responsible" ${role==='responsible'?'selected':''}>Ответственный</option><option value="manager" ${role==='manager'?'selected':''}>Руководитель</option><option value="admin" ${role==='admin'?'selected':''}>Администратор</option></select></label><label id="edit-user-org-wrap" class="${role==='responsible'?'':'hidden'}">Организация<select name="organizationId">${organizations.map(o=>`<option value="${o.id}" ${o.id===organizationId?'selected':''}>${esc(o.shortName)}</option>`).join('')}</select></label><label>Статус<select name="status"><option value="active" ${account.status!=='archive'?'selected':''}>Активный</option><option value="archive" ${account.status==='archive'?'selected':''}>Архивный</option></select></label><div class="modal-actions"><button type="button" class="button button--secondary" data-close-modal>Отмена</button><button class="button button--primary">Сохранить изменения</button></div></form>`);$('#edit-user-role').addEventListener('change',e=>$('#edit-user-org-wrap').classList.toggle('hidden',e.target.value!=='responsible'));}

  document.addEventListener('click', async (event) => {
    const route=event.target.closest('[data-route]')?.dataset.route;if(route){event.preventDefault();return navigate(route);}
    const adminTab=event.target.closest('[data-admin-tab]')?.dataset.adminTab;if(adminTab){state.adminTab=adminTab;return renderAdministration();}
    const adminEdit=event.target.closest('[data-admin-edit]');if(adminEdit){const type=adminEdit.dataset.adminEdit,entityId=adminEdit.dataset.adminId,d=state.adminSnapshot;if(type==='project')return editProjectModal(d.projects.find(item=>item.id===entityId));if(type==='organization')return editOrganizationModal(d.organizations.find(item=>item.id===entityId));return editUserModal(d.users.find(item=>item.id===entityId),type==='telegram');}
    const adminProject=event.target.closest('[data-admin-open-project]')?.dataset.adminOpenProject;if(adminProject&&adminProject!==state.projectId){state.projectId=adminProject;setContext();return renderAdministration();}
    const authProject=event.target.closest('[data-auth-project]')?.dataset.authProject;if(authProject){event.preventDefault();return selectTelegramProject(authProject);}
    if(event.target.closest('[data-copy-telegram-invite]')){const input=$('#telegram-invite-link');try{await navigator.clipboard.writeText(input.value);toast('Ссылка скопирована')}catch{input.select();document.execCommand('copy');toast('Ссылка скопирована')}return;}
    if(event.target.closest('[data-close-modal]')) return closeModal();
    if(event.target.id==='modal') return closeModal();
    const period=event.target.closest('[data-period]')?.dataset.period;if(period){state.filters.period=period;return navigate(state.route);}
    if(event.target.closest('[data-action="retry"]')) return navigate(state.route);
    if(event.target.closest('[data-action="new-milestone"]')) return milestoneModal();
    if(event.target.closest('[data-action="calendar"]')) return calendarModal();
    if(event.target.closest('[data-action="new-project"]')) return projectModal();
    if(event.target.closest('[data-action="new-organization"]')) return organizationModal();
    if(event.target.closest('[data-action="add-hierarchy"]')){const index=state.uploadHierarchy.length;state.uploadHierarchy.push('');const wrap=$('#hierarchy-fields');wrap.insertAdjacentHTML('beforeend',`<div class="hierarchy-row"><label class="field">Уровень ${index+1}<input data-hierarchy-index="${index}" value="" placeholder="Колонка"></label><button type="button" class="remove-row" data-remove-hierarchy="${index}">×</button></div>`);queueImportMappingSave();return;}
    const removeHierarchy=event.target.closest('[data-remove-hierarchy]');if(removeHierarchy){const index=Number(removeHierarchy.dataset.removeHierarchy);state.uploadHierarchy.splice(index,1);removeHierarchy.closest('.hierarchy-row').remove();$$('.hierarchy-row').forEach((row,i)=>{row.querySelector('label').childNodes[0].textContent=`Уровень ${i+1}`;row.querySelector('input').dataset.hierarchyIndex=i;row.querySelector('button').dataset.removeHierarchy=i});queueImportMappingSave();return;}
    if(event.target.closest('[data-action="save-settings"]')) return toast('Настройки сохранены');
    if(event.target.closest('[data-action="new-user"]')) return userModal();
    if(event.target.closest('[data-action="admin-report"]')) {state.draft.step=0;return navigate('report');}
    if(event.target.closest('[data-action="export-page"]')) return toast('Используйте выгрузку План / Факт в разделе «Графики»');
    if(event.target.closest('[data-report-no-facts]')){if(state.draft.facts.some(item=>Number(item.amount)>0)&&!confirm('Очистить введённые объёмы и отметить, что выполненных объёмов нет?'))return;state.draft.facts=[];state.draft.noFacts=true;state.draft.noWork=false;state.draft.step=Math.min(reportFlow().length-1,state.draft.step+1);return renderReport();}
    if(event.target.closest('[data-report-no-work]')){if(!confirm('Подтвердить, что сегодня организация не работала?'))return;state.draft.facts=[];state.draft.workers=[];state.draft.equipment=[];state.draft.photos=[];state.draft.noFacts=false;state.draft.noWork=true;return submitReport({skipValidation:true,noWork:true,button:event.target.closest('[data-report-no-work]')});}
    if(event.target.closest('[data-report-next]')){const error=validateStep();if(error)return toast(error,'error');if(state.draft.facts.some(item=>Number(item.amount)>0))state.draft.noFacts=false;state.draft.step=Math.min(reportFlow().length-1,state.draft.step+1);return renderReport();}
    if(event.target.closest('[data-report-prev]')){state.draft.step=Math.max(0,state.draft.step-1);return renderReport();}
    if(event.target.closest('[data-submit-report]'))return submitReport();
    const step=event.target.closest('[data-step]')?.dataset.step;if(step!==undefined){const nextStep=Number(step);if(state.draft.step===0&&nextStep>0){const error=validateReportFacts();if(error)return toast(error,'error');}state.draft.step=nextStep;return renderReport();}
    const action=event.target.closest('[data-action]')?.dataset.action;if(action==='add-fact'){state.draft.facts.push({workId:'',amount:''});return renderReport();}if(action==='add-workers'){state.draft.workers.push({name:'',count:''});return renderReport();}if(action==='add-equipment'){state.draft.equipment.push({name:'',count:''});return renderReport();}
    const remove=event.target.closest('[data-remove]');if(remove){state.draft[remove.dataset.remove].splice(Number(remove.dataset.index),1);return renderReport();}
    const photo=event.target.closest('[data-remove-photo]');if(photo){state.draft.photos.splice(Number(photo.dataset.removePhoto),1);return renderReport();}
  });

  document.addEventListener('input',event=>{if(event.target.matches('[data-hierarchy-index]'))state.uploadHierarchy[Number(event.target.dataset.hierarchyIndex)]=event.target.value.trim().toUpperCase();if(event.target.matches('#schedule-import-form input:not([type="file"]):not([name="month"])'))queueImportMappingSave();if(event.target.matches('[data-admin-search-input]'))filterAdminRows();});
  document.addEventListener('change',async event=>{if(event.target.id==='org-filter'){state.filters.organizationId=event.target.value;state.filters.workId='all';navigate(state.route)}if(event.target.id==='work-filter'){state.filters.workId=event.target.value;navigate(state.route)}if(event.target.id==='delays-filter'){state.filters.delays=event.target.checked;navigate(state.route)}if(event.target.id==='end-date-filter'){state.filters.endDate=event.target.value;navigate(state.route)}if(event.target.id==='sort-filter'){state.filters.sort=event.target.value;navigate(state.route)}if(event.target.matches('[data-admin-status-filter]'))filterAdminRows();if(event.target.matches('[data-admin-project]')){state.projectId=event.target.value;setContext();return renderAdministration();}if(event.target.matches('[data-org-setting]')){const card=event.target.closest('.org-settings-card')||event.target.closest('tr'),settings=Object.fromEntries($$('[data-org-setting]',card).map(input=>[input.dataset.orgSetting,input.checked]));try{await api(`/api/admin/organizations/${event.target.dataset.orgId}/settings`,{method:'POST',body:JSON.stringify({projectId:state.projectId,...settings})});const full=await api('/api/bootstrap');state.organizations=full.organizations;toast('Настройки отчёта сохранены')}catch(error){event.target.checked=!event.target.checked;toast(error.message,'error')}}});
  document.addEventListener('submit',async event=>{
    event.preventDefault();
    if(event.target.id==='login-form')return login($('#login').value,$('#password').value);
    if(event.target.id==='schedule-import-form')return uploadSchedule(event.target);
    if(event.target.id==='milestone-form'){const fd=new FormData(event.target);try{await api('/api/milestones',{method:'POST',body:JSON.stringify({projectId:state.projectId,name:fd.get('name'),date:fd.get('date')})});closeModal();toast('Контрольная веха создана');navigate('milestones')}catch(e){toast(e.message,'error')}return;}
    if(event.target.id==='project-form'){const fd=new FormData(event.target);try{await api('/api/admin/projects',{method:'POST',body:JSON.stringify({contextProjectId:state.projectId,name:fd.get('name'),shortName:fd.get('shortName'),customerOrganizationFullName:fd.get('customerOrganizationFullName')})});closeModal();const full=await api('/api/bootstrap');state.projects=full.projects;state.user=full.user;renderChrome();toast('Объект создан');navigate(state.role==='admin'?'administration':'projects')}catch(e){toast(e.message,'error')}return;}
    if(event.target.id==='organization-form'){const fd=new FormData(event.target);try{await api('/api/admin/organizations',{method:'POST',body:JSON.stringify({projectId:state.projectId,fullName:fd.get('fullName'),shortName:fd.get('shortName'),workforce:fd.get('workforce')==='on',machinery:fd.get('machinery')==='on',photos:fd.get('photos')==='on'})});closeModal();const full=await api('/api/bootstrap');state.organizations=full.organizations;toast('Организация создана');navigate(state.role==='admin'?'administration':'organizations')}catch(e){toast(e.message,'error')}}
    if(event.target.id==='user-form'){const fd=new FormData(event.target),name=[fd.get('lastName'),fd.get('firstName'),fd.get('middleName')].map(value=>String(value||'').trim()).filter(Boolean).join(' ');try{const data=await api('/api/admin/users',{method:'POST',body:JSON.stringify({projectId:state.projectId,name,login:fd.get('login'),password:fd.get('password'),telegramId:fd.get('telegramId'),createTelegramInvite:fd.get('createTelegramInvite')==='on',role:fd.get('role'),organizationId:fd.get('organizationId')})});toast('Пользователь создан');if(data.telegramInvite){state.adminTab='users';await renderAdministration();return telegramInviteModal(data.telegramInvite,data.user)}closeModal();navigate(state.role==='admin'?'administration':'users')}catch(e){toast(e.message,'error')}}
    if(event.target.id==='edit-project-form'){const fd=new FormData(event.target);try{await api(`/api/admin/projects/${event.target.dataset.entityId}`,{method:'POST',body:JSON.stringify({contextProjectId:state.projectId,name:fd.get('name'),shortName:fd.get('shortName'),customerOrganizationFullName:fd.get('customerOrganizationFullName'),status:fd.get('status')})});await refreshAdministration('Объект обновлён')}catch(e){toast(e.message,'error')}return;}
    if(event.target.id==='edit-organization-form'){const fd=new FormData(event.target);try{await api(`/api/admin/organizations/${event.target.dataset.entityId}`,{method:'PATCH',body:JSON.stringify({projectId:state.projectId,fullName:fd.get('fullName'),shortName:fd.get('shortName'),status:fd.get('status'),workforce:fd.get('workforce')==='on',machinery:fd.get('machinery')==='on',photos:fd.get('photos')==='on'})});await refreshAdministration('Организация обновлена')}catch(e){toast(e.message,'error')}return;}
    if(event.target.id==='edit-user-form'){const fd=new FormData(event.target);try{await api(`/api/admin/users/${event.target.dataset.entityId}`,{method:'PATCH',body:JSON.stringify({projectId:state.projectId,name:fd.get('name'),login:fd.get('login'),password:fd.get('password'),telegramId:fd.get('telegramId'),role:fd.get('role'),organizationId:fd.get('organizationId'),status:fd.get('status')})});await refreshAdministration('Пользователь обновлён')}catch(e){toast(e.message,'error')}return;}
  });

  async function login(login,password){const error=$('#login-error');error.textContent='';const button=$('#login-form button[type="submit"]');button.disabled=true;try{const telegramLink=state.authMode==='telegram-link';if(telegramLink&&!$('#telegram-link-confirm').checked)throw new Error('Подтвердите привязку Telegram ID');const endpoint=telegramLink?'/api/auth/telegram/link':'/api/auth/login';const payload=telegramLink?{initData:state.telegramInitData,login,password,confirmLink:true}:{login,password};const data=await api(endpoint,{method:'POST',body:JSON.stringify(payload)});if(data.linked)toast('Telegram ID успешно привязан к аккаунту');await boot(data,{telegramLaunch:telegramLink});}catch(e){error.textContent=e.message;}finally{button.disabled=false;}}
  $('#toggle-password').addEventListener('click',()=>{$('#password').type=$('#password').type==='password'?'text':'password'});
  $('#mobile-menu').addEventListener('click',()=>{$('.sidebar').classList.add('open');$('#overlay').classList.remove('hidden')});
  $('#overlay').addEventListener('click',closePopovers);
  $('#project-switcher').addEventListener('click',()=>{const p=$('#project-popover'),box=$('#project-switcher').getBoundingClientRect();p.style.left=`${box.left}px`;p.style.top=`${box.bottom+7}px`;p.innerHTML=state.projects.map(x=>{const a=state.user.assignments.find(y=>y.projectId===x.id);return `<button data-project="${x.id}" class="${x.id===state.projectId?'active':''}"><span><b>${esc(x.shortName)}</b><br><small>${roleNames[a.role]}</small></span>${x.id===state.projectId?'✓':''}</button>`}).join('');p.classList.toggle('hidden');$('#user-popover').classList.add('hidden')});
  $('#project-popover').addEventListener('click',e=>{const id=e.target.closest('[data-project]')?.dataset.project;if(id){state.projectId=id;state.filters={...state.filters,endDate:'',organizationId:'all',workId:'all',delays:false};setContext();const allowed=(navByRole[state.role]||[]).flatMap(g=>g[1]).map(x=>x[0]);navigate(allowed.includes(state.route)?state.route:projectLandingRoute(state.role))}});
  $('#user-menu').addEventListener('click',()=>{const p=$('#user-popover'),box=$('#user-menu').getBoundingClientRect();p.style.right=`${innerWidth-box.right}px`;p.style.top=`${box.bottom+7}px`;p.classList.toggle('hidden');$('#project-popover').classList.add('hidden')});
  $('#user-popover').addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='logout'){await api('/api/auth/logout',{method:'POST'});if(state.telegramInitData&&window.Telegram?.WebApp?.close)return window.Telegram.WebApp.close();showLogin('web')}if(action==='profile')navigate('profile')});
  $('#auth-retry').addEventListener('click',initializeAuthentication);
  window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);if(state.user&&state.projectId&&state.authMode!=='telegram-project'&&route!==state.route)navigate(route)});

  function telegramInitDataFromLocation(){
    const sources=[new URLSearchParams(location.search),new URLSearchParams(location.hash.replace(/^#/,''))];
    for(const params of sources){const value=params.get('tgWebAppData');if(value)return value;}
    return '';
  }

  async function telegramLaunchContext(){
    let tg=window.Telegram?.WebApp;
    let initData=tg?.initData||telegramInitDataFromLocation();
    if(tg||initData)return{tg,initData};
    const sdk=$('#telegram-web-app-sdk');
    if(sdk){
      await new Promise(resolve=>{
        let finished=false;
        const finish=()=>{if(finished)return;finished=true;resolve();};
        sdk.addEventListener('load',finish,{once:true});
        sdk.addEventListener('error',finish,{once:true});
        setTimeout(finish,1500);
      });
    }
    tg=window.Telegram?.WebApp;
    initData=tg?.initData||telegramInitDataFromLocation();
    return{tg,initData};
  }

  async function initializeAuthentication(){
    const launchTicket=new URLSearchParams(location.search).get('ticket');
    if(launchTicket){
      showAuthCheck();
      $('#auth-check-title').textContent='Открываем План / Факт';
      $('#auth-check-text').textContent='Подтверждаем вход…';
      try{const data=await api('/api/auth/exchange',{method:'POST',body:JSON.stringify({ticket:launchTicket})});const cleanUrl=new URL(location.href);cleanUrl.searchParams.delete('ticket');history.replaceState(null,'',cleanUrl.pathname+cleanUrl.search+cleanUrl.hash);return await boot(data);}
      catch(error){return showLogin('web');}
    }
    const{tg,initData}=await telegramLaunchContext();
    if(!initData){state.telegramInitData='';state.pendingTelegramId='';return showLogin('web');}
    tg?.ready?.();tg?.expand?.();state.telegramInitData=initData;showAuthCheck();
    try{const data=await api('/api/auth/telegram',{method:'POST',body:JSON.stringify({initData})});await boot(data,{telegramLaunch:true});}
    catch(error){if(error.code==='TELEGRAM_ACCOUNT_NOT_LINKED')return showLogin('telegram',error.data?.telegramId);showAuthCheck(error.message);}
  }

  initializeAuthentication();
})();
